#!/usr/bin/env bash
#: SCIAME DI AGENTI PER CLAUDE CODE, versione 4.0 — AGENT SWARM FOR CLAUDE CODE, version 4.0
#:
#: Un file solo: i documenti, il database dei professionisti e il motore dello sciame, più i comandi per installarlo e
#: convocarlo. / One file: the swarm's documents, its database of professionals and its engine, plus the commands to
#: install and convene it.
#:
#: Serve / Needs: bash, python3 >= 3.8 (solo libreria standard / standard library only), Claude Code (`claude`).
#:
#:   bash sciame.sh installa [--lingua it|en] [--istruzioni] [--forza] [--cartella DIR] [--locale DIR]
#:   bash sciame/sciame.sh <singolo|ventaglio|classica|giuria|completa|plenaria|esperto|auto> "richiesta"
#:   bash sciame/sciame.sh aiuto            # tutti i comandi, nella lingua scelta / every command, in the chosen language
#:
#: English command names work too: install, help, language, single, fan-out, classic, jury, full, plenary, expert.

set -euo pipefail

QUESTO="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)/$(basename "${BASH_SOURCE[0]}")"

errore() { printf 'sciame: %s\n' "$*" >&2; exit 1; }

serve_python() {
    command -v python3 >/dev/null 2>&1 || errore "manca python3 / python3 is missing (>= 3.8)"
    python3 -I -B -c 'import sys; sys.exit(0 if sys.version_info >= (3, 8) else 1)' \
        || errore "python3 è troppo vecchio / python3 is too old: >= 3.8"
}

# I file che stanno in fondo a questo file, in una cartella. / The files at the end of this file, into a folder.
estrai() {
    # Un nome di file è relativo, senza «..», senza componenti vuoti: altrimenti l'estrazione si ferma (codice 2).
    awk -v dest="$1" '
        /^#==== sciame\.sh: file [A-Za-z0-9_.\/-]+ ====$/ {
            if (out) close(out)
            nome = $4
            if (nome ~ /^\// || nome ~ /(^|\/)\.\.(\/|$)/ || nome ~ /\/\// || (nome in visti)) { cattivo = nome; exit 2 }
            visti[nome] = 1
            out = dest "/" nome
            d = out; sub(/\/[^\/]*$/, "", d); system("mkdir -p \"" d "\"")
            printf "" > out; next }
        /^#==== sciame\.sh: fine dei file ====$/ { if (out) close(out); out = ""; next }
        out { print > out }
        END { if (cattivo != "") { print "sciame: nome di file non ammesso: " cattivo > "/dev/stderr"; exit 2 } }
    ' "$QUESTO" || errore "sciame.sh contiene un nome di file non ammesso / an unsafe file name: non lo installo"
    [ -f "$1/motore/sciame.py" ] && [ -f "$1/db/professionisti.json" ] \
        || errore "questo file è incompleto / this file is incomplete: scaricalo di nuovo / download it again"
}

# La cartella dello sciame da config.json, validata: relativa, senza «..», diversa da «.».
cartella_da_config() {
    local f="$1/.sciame/config.json"
    [ -f "$f" ] && [ ! -L "$f" ] || { printf 'sciame'; return; }
    python3 -I -B -c '
import json, os, sys
c = json.load(open(sys.argv[1])).get("cartella", "sciame")
parti = c.split("/")
if not c or os.path.isabs(c) or ".." in parti or c in (".", "./") or "" in parti:
    sys.exit("sciame: cartella non ammessa in .sciame/config.json: %r" % c)
print(c, end="")' "$f"
}

# La cartella dello sciame: quella di questo file se è una copia installata (RADICE e FABBRICA.json accanto),
# altrimenti quella di .sciame/config.json del progetto, altrimenti <progetto>/sciame.
trova() {
    local qui; qui="$(dirname "$QUESTO")"
    if [ -n "${RADICE:-}" ]; then
        RADICE="$(cd "$RADICE" && pwd -P)"
        [ -n "${CARTELLA:-}" ] || CARTELLA="$(cartella_da_config "$RADICE")" || exit 1
    elif [ -f "$qui/RADICE" ] && [ -f "$qui/FABBRICA.json" ] && [ -f "$qui/motore/sciame.py" ]; then
        RADICE="$(cd "$qui/$(cat "$qui/RADICE")" && pwd -P)"
        CARTELLA="$(python3 -I -B -c 'import os,sys; print(os.path.relpath(sys.argv[1], sys.argv[2]))' "$qui" "$RADICE")"
    else
        RADICE="$PWD"
        [ -n "${CARTELLA:-}" ] || CARTELLA="$(cartella_da_config "$RADICE")" || exit 1
    fi
}

installa() {
    serve_python
    if [ "$RADICE" = "/" ] || [ "$RADICE" = "$(cd "${HOME:-/}" && pwd -P)" ]; then
        errore "$RADICE non sembra un progetto / does not look like a project: -C CARTELLA installa"
    fi
    local args=()
    while [ $# -gt 0 ]; do
        case "$1" in
            --cartella|--folder) CARTELLA="${2%/}"; shift 2 ;;
            --lingua|--language) args+=(--lingua "$2"); shift 2 ;;
            --locale|--local) args+=(--locale "$2"); shift 2 ;;
            --istruzioni|--instructions) args+=(--istruzioni); shift ;;
            --forza|--force) args+=(--forza); shift ;;
            --gestiti-dal-progetto|--project-managed) args+=(--gestiti-dal-progetto); shift ;;
            *) errore "installa: opzione sconosciuta / unknown option: $1" ;;
        esac
    done
    SCIAME_TMP="$(mktemp -d)"
    trap 'rm -rf "${SCIAME_TMP:-}"' EXIT
    estrai "$SCIAME_TMP"
    cp "$QUESTO" "$SCIAME_TMP/sciame.sh"
    python3 -I -B "$SCIAME_TMP/motore/sciame.py" installa --da "$SCIAME_TMP" --radice "$RADICE" --cartella "$CARTELLA" ${args[@]+"${args[@]}"}
}

principale() {
    RADICE=""
    CARTELLA=""   # mai dall'ambiente: la cartella viene da --cartella, dalla copia installata o da .sciame/config.json
    if [ "${1:-}" = "-C" ]; then
        [ $# -ge 2 ] || errore "-C vuole una cartella / -C wants a folder"
        RADICE="$2"; shift 2
    fi
    local comando="${1:-aiuto}"
    [ $# -eq 0 ] || shift
    case "$comando" in
        install) comando=installa ;; help|-h|--help) comando=aiuto ;; language) comando=lingua ;;
        single) comando=singolo ;; fan-out|fanout) comando=ventaglio ;; classic) comando=classica ;;
        jury) comando=giuria ;; light-jury) comando=giuria-leggera ;; full) comando=completa ;; plenary) comando=plenaria ;; expert) comando=esperto ;;
        roles) comando=ruoli ;; professionals) comando=professionisti ;; check) comando=controlla ;;
        regenerate) comando=rigenera ;; remove) comando=rimuovi ;; instructions) comando=istruzioni ;;
        models) comando=modelli ;; requests) comando=richieste ;; count) comando=conta ;; approve) comando=approva ;;
        propose) comando=proponi ;; build) comando=costruisci ;; verify) comando=verifica ;; tests) comando=prove ;;
        update) comando=aggiorna ;; import-cards) comando=importa-schede ;;
    esac
    trova
    case "$comando" in
        aiuto)
            sed -n 's/^#: \{0,1\}//p' "$QUESTO"
            if [ -f "$RADICE/$CARTELLA/motore/sciame.py" ]; then
                local l="it"; [ -f "$RADICE/$CARTELLA/LINGUA" ] && l="$(head -c 8 "$RADICE/$CARTELLA/LINGUA" | tr -d '\n')"
                case "$l" in [a-z][a-z]) ;; *) l="it" ;; esac
                [ -f "$RADICE/$CARTELLA/documenti/$l/_AIUTO.txt" ] && cat "$RADICE/$CARTELLA/documenti/$l/_AIUTO.txt"
            fi ;;
        installa) installa "$@" ;;
        aggiorna)
            # Con i file di questo sciame.sh, senza toccare quelli modificati nel progetto (vanno accanto, .nuovo).
            installa "$@" ;;
        prove)
            serve_python
            [ -f "$RADICE/$CARTELLA/motore/sciame.py" ] || errore "sciame non installato / not installed"
            local rc=0
            for p in "$RADICE/$CARTELLA"/prove/prova_*.py; do python3 -I -B "$p" || rc=1; done
            exit "$rc" ;;
        *)
            serve_python
            [ -f "$RADICE/$CARTELLA/motore/sciame.py" ] \
                || errore "in $RADICE lo sciame non c'è ancora / is not installed yet: bash sciame.sh installa"
            exec python3 -I -B "$RADICE/$CARTELLA/motore/sciame.py" --sciame "$RADICE/$CARTELLA" "$comando" "$@" ;;
    esac
}

principale "$@"
exit
# Da qui in giù ci sono i file dello sciame, che «installa» scrive in sciame/. Bash non arriva oltre «exit».
: <<'SCIAME_FINE_DEI_FILE'
#==== sciame.sh: file motore/convoca.py ====
#!/usr/bin/env python3
"""Sciame 4.0: prepara lo scheletro di una convocazione (singolo, ventaglio, classica o completa) e ne controlla i
cancelli. Giuria e plenaria si contano con giuria.py.

È la forma generale della convocazione a grafo. Restano:
- le corsie cieche, con i canarini e la mappa nota solo al coordinatore;
- la foto delle letture;
- i sigilli;
- i cancelli legati con lo sha256;
- la selezione solo dal triage;
- la chiusura anticipata dei rami.

Non lancia agenti e non approva niente da solo. Solo libreria standard, niente rete.

Comandi (i percorsi diventano assoluti):
  ruoli     [--domanda TESTO]     i ruoli e i profili; con la domanda, i ruoli le cui parole chiave vi compaiono
  prepara   --nome N --strategia singolo|ventaglio|classica|completa --profilo P --domanda TESTO [--ruoli a,b] [--dest D] [--seme S]
            [--n N --forma fette|gara|mista --regola primo|classifica|migliore]   (ventaglio)
  fotografa C                     appena le corsie hanno consegnato, prima di leggerle
  cancello  C FASE --note TESTO [--non-consegnati RUOLO,…] [--verifica]
            FASE = f0, f1, f2, f3/H-001, f4/H-001, f5
  sigilla   C FILE…               ora e sha256 in SIGILLI.jsonl
  seleziona C H-001 [H-002 H-003] [--radicale H-00x] [--responsabile SIGLA]
  chiudi-ramo C H-00x --motivo TESTO
  stato     C
"""
from __future__ import annotations

import argparse
import datetime
import hashlib
import json
import os
import random
import re
import secrets
import sys
from pathlib import Path

QUI = Path(__file__).resolve().parent
BASE = QUI.parent if QUI.name == "motore" else QUI  # la cartella dello sciame, dove sta catalogo.json
VERSIONE = "4.0"
STRATEGIE = ("singolo", "ventaglio", "classica", "completa")
FORME = ("fette", "gara", "mista")
REGOLE = ("primo", "classifica", "migliore")
CAMPI_CONTRATTO = ("Domanda", "Criterio", "Ingressi", "Vincoli", "Esclusioni", "Quota", "Profilo")
CAMPI_EN = {"Domanda": "Question", "Criterio": "Criterion", "Ingressi": "Inputs", "Vincoli": "Constraints",
            "Esclusioni": "Exclusions", "Quota": "Budget", "Profilo": "Profile"}
DA_COMPILARE = "<da compilare>"
DA_COMPILARE_EN = "<to fill in>"


def LINGUA() -> str:
    """La lingua dello sciame (sciame/LINGUA, o SCIAME_LINGUA): le consegne e il contratto si scrivono in quella."""
    import os
    l = os.environ.get("SCIAME_LINGUA") or ((BASE / "LINGUA").read_text(encoding="utf-8").strip()
                                             if (BASE / "LINGUA").is_file() else "it")
    return "en" if l == "en" else "it"


T = {
    "it": {"consegna": "Consegna", "fase": "fase", "agente": "Agente", "convocazione": "Convocazione",
           "strategia": "strategia", "profilo": "profilo", "domanda": "Domanda", "ingressi": "Ingressi (leggi solo questi):",
           "uscita": "Uscita", "uscita_coda": "al più due pagine; `stato.md` nella stessa cartella se lavori più di dieci minuti.",
           "tempo": "Tempo", "tempo_coda": "minuti. Prove al più di classe 1 (cinque minuti ciascuna) salvo diversa indicazione.",
           "al_piu": "al più", "scrivi": "Scrivi solo in", "scrivi_coda": "Niente modifiche al progetto, niente git, niente segreti.",
           "vietato": "Spazio vietato:", "vietato_coda": "le cartelle degli altri agenti della convocazione, e ciò che il contratto esclude.",
           "criterio": "Criterio di fatto:", "criterio_coda": "quello del contratto; se la missione qui sotto ne dà uno più stretto, vale quello.",
           "esito": "Esito in testa alla consegna:", "esito_coda": "FATTO, PROBLEMI o BLOCCATO, con le prove (regola 11 del preambolo).",
           "canarino": "(La prima riga della tua consegna deve essere questa riga del canarino.)",
           "che_cosa": "Che cosa fare", "contratto": "Contratto della convocazione", "creato": "Creato",
           "principi": "Principi del progetto", "principi_testo": "Quelli che non si negoziano, se ci sono; altrimenti «nessuno oltre il preambolo».",
           "fetta": "Fetta {k} di {n}: <da compilare>"},
    "en": {"consegna": "Brief", "fase": "phase", "agente": "Agent", "convocazione": "Convening",
           "strategia": "strategy", "profilo": "profile", "domanda": "Question", "ingressi": "Inputs (read only these):",
           "uscita": "Output", "uscita_coda": "two pages at most; `stato.md` in the same folder if you work more than ten minutes.",
           "tempo": "Time", "tempo_coda": "minutes. Tests of class 1 at most (five minutes each) unless stated otherwise.",
           "al_piu": "at most", "scrivi": "Write only in", "scrivi_coda": "No changes to the project, no git, no secrets.",
           "vietato": "Forbidden scope:", "vietato_coda": "the folders of the other agents of the convening, and what the contract excludes.",
           "criterio": "Done criterion:", "criterio_coda": "the contract's; if the mission below gives a stricter one, that one holds.",
           "esito": "Outcome at the top of the deliverable:", "esito_coda": "DONE, ISSUES or BLOCKED, with the evidence (rule 11 of the preamble).",
           "canarino": "(The first line of your deliverable must be this canary line.)",
           "che_cosa": "What to do", "contratto": "Contract of the convening", "creato": "Created",
           "principi": "Project principles", "principi_testo": "The non-negotiable ones, if any; otherwise «none beyond the preamble».",
           "fetta": "Slice {k} of {n}: <to fill in>"},
}
ID = re.compile(r"\bH-?0*(\d{1,3})\b")
LIMITE_F1 = 40  # minuti per una consegna di f1
LIMITE_RAMO = 60


class Errore(Exception):
    pass


def ora() -> str:
    return datetime.datetime.now().astimezone().isoformat(timespec="seconds")


def sha(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()


def norm_id(s: str) -> str:
    m = re.fullmatch(r"H-?0*(\d{1,3})", s.strip(), re.I)
    if not m:
        raise Errore(f"ID malformato: {s} (la forma è H-001)")
    return f"H-{int(m.group(1)):03d}"


def catalogo() -> dict:
    """I ruoli e i profili: il catalogo accanto a questo script, fatto da genera_agenti.py."""
    p = BASE / "catalogo.json"
    if not p.exists():
        raise Errore(f"non trovo {p}: lo scrive bash sciame/sciame.sh rigenera")
    return json.loads(p.read_text(encoding="utf-8"))


def carica(c: Path) -> dict:
    p = c / "MANIFESTO.json"
    if not p.exists():
        raise Errore(f"{c} non è una convocazione (manca MANIFESTO.json)")
    return json.loads(p.read_text(encoding="utf-8"))


def salva(c: Path, m: dict) -> None:
    (c / "MANIFESTO.json").write_text(json.dumps(m, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")


def traduci_missione(testo: str) -> str:
    """La missione in inglese, dalla tabella motore/missioni_en.json: le chiavi sono i testi italiani, con i segnaposto
    {…} che si ritrovano nel testo; il resto dopo la missione (per esempio la fetta) si conserva."""
    tabella = QUI / "missioni_en.json"
    if not tabella.is_file():
        return testo
    for it, en in json.loads(tabella.read_text(encoding="utf-8")).items():
        pezzi = re.split(r"\{[^{}]*\}", it)
        rx = "(.+?)".join(re.escape(x) for x in pezzi)
        m = re.match(rx + r"(.*)\Z", testo, re.S)
        if m:
            gruppi = m.groups()
            return en.format(*gruppi[:-1]) + gruppi[-1]
    return testo


def consegna(m: dict, c: Path, cartella: Path, ruolo: str, fase: str, uscita: str, missione: str, ingressi: list[Path],
             *, canarino: str | None = None, minuti: int = LIMITE_F1, h: str | None = None) -> Path:
    cartella.mkdir(parents=True, exist_ok=True)
    x = T[LINGUA()]
    if LINGUA() == "en":
        missione = traduci_missione(missione)
    righe = []
    if canarino:
        righe += [f"Canarino: {canarino}", "", x["canarino"], ""]
    righe += [
        f"# {x['consegna']}: {ruolo}, {x['fase']} {fase}" + (f", {h}" if h else ""),
        "",
        f"- **{x['agente']}:** `sciame-{ruolo}`",
        f"- **{x['convocazione']}:** {m['nome']} ({x['strategia']} {m['strategia']}, {x['profilo']} {m['profilo']})",
        f"- **{x['domanda']}:** {m['domanda']}",
        f"- **{x['ingressi']}**",
        *[f"  - `{p}`" for p in ingressi],
        f"- **{x['uscita']}:** `{cartella / uscita}`, {x['uscita_coda']}",
        f"- **{x['tempo']}:** {x['al_piu']} {minuti} {x['tempo_coda']}",
        f"- **{x['scrivi']}** `{cartella}`. {x['scrivi_coda']}",
        f"- **{x['vietato']}** {x['vietato_coda']}",
        f"- **{x['criterio']}** {x['criterio_coda']}",
        f"- **{x['esito']}** {x['esito_coda']}",
        "",
        f"## {x['che_cosa']}",
        "",
        missione,
        "",
    ]
    (cartella / "TASK.md").write_text("\n".join(righe), encoding="utf-8")
    return cartella / "TASK.md"


def contratto(m: dict) -> str:
    l = LINGUA()
    x = T[l]
    righe = [f"# {x['contratto']} {m['nome']}", "", f"{x['strategia'].capitalize()}: {m['strategia']}. {x['creato']}: {m['creato']}.", ""]
    valori = {"Domanda": m["domanda"], "Profilo": m["profilo"]}
    for campo in CAMPI_CONTRATTO:
        righe += [f"## {CAMPI_EN[campo] if l == 'en' else campo}", "",
                  valori.get(campo, DA_COMPILARE_EN if l == "en" else DA_COMPILARE), ""]
    righe += [f"## {x['principi']}", "", x["principi_testo"], ""]
    return "\n".join(righe)


MISSIONI = {
    "A": "Sei nella corsia A, conservativa. Diagnosi del problema e dei vincoli; due proposte, ciascuna con l'enunciato, il "
         "guadagno atteso, i vincoli, chi la può provare e il falsificatore più economico (al più cinque minuti) con "
         "l'esito atteso scritto prima in PREVISIONI.md.",
    "B": "Sei nella corsia B, divergente. Il creativo: al più quattro idee da campi lontani, ciascuna con il meccanismo "
         "tradotto e il test. Il rovesciatore: al più due rovesciamenti dei presupposti, ciascuno con l'alternativa "
         "concreta e il test. Ogni idea con il falsificatore più economico in PREVISIONI.md.",
    "tutti": "Tornata globale, dal tuo punto di vista: al più tre osservazioni o proposte, ciascuna con la prova o il "
             "falsificatore. Se il tuo campo non c'entra, scrivi «non pertinente: …» in una riga. Al più mezza pagina.",
    "singolo": "Esegui la richiesta nel tuo ruolo, per intero, e rileggiti con le tue «domande che si pone sempre» prima di "
               "consegnare.",
    "fetta": "Sei un agente di un ventaglio, con una fetta del lavoro: la tua è scritta qui sotto dal coordinatore. Fai solo "
             "la tua fetta, per intero, e verifica il criterio di fatto prima di consegnare.",
    "gara": "Sei un braccio di una gara: altri agenti hanno la tua stessa consegna, e il coordinatore sceglierà con la regola "
            "dichiarata nel contratto. Lavora da solo, per intero, e verifica il criterio di fatto prima di consegnare.",
}


def ruoli(ns) -> None:
    """I ruoli, e i profili. Con una domanda, solo i ruoli di cui una parola chiave compare nel testo, per intero."""
    cat = catalogo()
    nuclei = {n["id"]: n["nome"].lower() for n in cat["nuclei"]}
    testo = (ns.domanda or "").lower()
    trovati = 0
    for r in cat["ruoli"]:
        parole = list(dict.fromkeys(p.lower() for p in r["parole"]
                                    if re.search(rf"(?<!\w){re.escape(p.lower())}(?!\w)", testo))) if testo else []
        if testo and not parole:
            continue
        trovati += 1
        print(f"sciame-{r['sigla']}: {r['nome']} (nucleo {nuclei[r['nucleo']]})" + (f"; parole: {', '.join(parole)}" if parole else ""))
    if testo and not trovati:
        print("Nessuna parola chiave dei ruoli compare nella domanda: scegli dal profilo.")
    print("Profili:")
    for nome, p in cat["profili"].items():
        print(f"  {nome}: {p['per']} (corsia A: {', '.join(p['A'])})")


def prepara(ns) -> None:
    cat = catalogo()
    sigle = {r["sigla"] for r in cat["ruoli"]}
    if ns.profilo not in cat["profili"]:
        raise Errore(f"profilo sconosciuto: {ns.profilo} (sono: {', '.join(cat['profili'])})")
    extra = [r.strip() for r in (ns.ruoli or "").split(",") if r.strip()]
    for r in extra:
        if r not in sigle:
            raise Errore(f"ruolo sconosciuto: {r}")
    prof = cat["profili"][ns.profilo]
    seme = ns.seme if ns.seme is not None else secrets.randbelow(10**9)
    rnd = random.Random(seme)
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M")
    nome = re.sub(r"[^A-Za-z0-9_-]+", "-", ns.nome).strip("-")[:40] or "convocazione"
    dest = Path(ns.dest).resolve()
    c = dest / f"{stamp}-{nome}"
    if c.exists():
        raise Errore(f"esiste già {c}")
    c.mkdir(parents=True)
    m = {"versione": VERSIONE, "nome": nome, "strategia": ns.strategia, "profilo": ns.profilo, "domanda": ns.domanda,
         "seme": seme, "creato": ora(), "f1": {}, "selezionate": [], "radicale": None}
    (c / "CONTRATTO.md").write_text(contratto(m), encoding="utf-8")
    (c / "f0").mkdir()
    ingressi = [c / "CONTRATTO.md"]
    mappa = {}
    if ns.strategia == "ventaglio":
        if not ns.n or ns.n < 2 or ns.n > 16:
            raise Errore("il ventaglio vuole --n fra 2 e 16")
        if ns.forma not in FORME or (ns.forma != "fette" and ns.regola not in REGOLE):
            raise Errore("il ventaglio vuole --forma fette|gara|mista e, per gara e mista, --regola primo|classifica|migliore")
        m["ventaglio"] = {"n": ns.n, "forma": ns.forma, "regola": ns.regola}
        ruoli_v = extra or prof["A"][:1]
        for k in range(1, ns.n + 1):
            ruolo = ruoli_v[(k - 1) % len(ruoli_v)]
            cartella = c / "f1" / f"agente-{k}"
            consegna(m, c, cartella, ruolo, "f1", "CONSEGNA.md", MISSIONI["gara" if ns.forma == "gara" else "fetta"]
                     + ("" if ns.forma == "gara" else "\n\n" + T[LINGUA()]["fetta"].format(k=k, n=ns.n)), ingressi)
            m["f1"][f"agente-{k}"] = {"cartella": str(cartella), "corsia": ns.forma, "ruolo": ruolo}
    elif ns.strategia == "singolo":
        ruolo = extra[0] if extra else prof["A"][0]
        consegna(m, c, c / "f1" / ruolo, ruolo, "f1", "CONSEGNA.md", MISSIONI["singolo"], ingressi)
        m["f1"][ruolo] = {"cartella": str(c / "f1" / ruolo), "corsia": "singolo"}
    else:
        if ns.strategia == "classica":
            corsie = {"A": list(dict.fromkeys(prof["A"] + [r for r in extra if r not in prof["B"]])), "B": prof["B"]}
        else:
            # La tornata globale è dei professionisti; i sottoprofessionisti entrano solo se nominati.
            corsie = {"tutti": [r["sigla"] for r in cat["ruoli"] if r["sigla"] != "arbitro"
                                and (r.get("tipo", "professionista") == "professionista" or r["sigla"] in extra)]}
        canarini = {}
        for corsia, ruoli in corsie.items():
            for ruolo in ruoli:
                cartella = c / "f1" / secrets.token_hex(6)
                # Nella classica un canarino per corsia, nella completa uno per ruolo: ognuno è cieco agli altri.
                chiave = corsia if ns.strategia == "classica" else ruolo
                canarini.setdefault(chiave, f"sciame-canarino-{secrets.token_hex(8)}")
                consegna(m, c, cartella, ruolo, "f1", "CONSEGNA.md", MISSIONI[corsia], ingressi, canarino=canarini[chiave])
                mappa[ruolo] = {"cartella": str(cartella), "corsia": corsia, "canarino": canarini[chiave]}
                m["f1"][ruolo] = {"cartella": str(cartella), "corsia": corsia}
        if ns.strategia == "completa":
            consegna(m, c, c / "f1c" / "arbitro", "arbitro", "f1c", "CONSOLIDAMENTO.md",
                     "Consolida i contributi della tornata globale, prima per nucleo e poi d'insieme: fatti F# con lo stato, "
                     "contraddizioni K#, idee candidate con l'origine (ruolo e file), domande aperte, ruoli da chiamare dopo. "
                     "Niente voto. Le idee candidate entreranno in f2 come schede d'ingresso.",
                     ingressi + [Path(v["cartella"]) / "CONSEGNA.md" for v in mappa.values()], minuti=60)
        f1_consegne = [Path(v["cartella"]) / "CONSEGNA.md" for v in m["f1"].values()]
        if ns.strategia == "completa":
            f1_consegne = [c / "f1c" / "arbitro" / "CONSOLIDAMENTO.md"]
        traduttore = next((r for r in prof["traduce"] + ["formalista", "logico"] if r not in m["f1"]), "logico")
        f2 = c / "f2"
        consegna(m, c, f2 / "01-traduzione", traduttore, "f2", "SCHEDE.md",
                 "Una scheda per idea: oggetto, enunciato preciso, tipo, rischi, ipotesi critica e controesempio candidato, "
                 "come la si verifica. Niente fusioni: due idee sono la stessa solo se enunciato e tipo coincidono. Ogni "
                 "scheda dice da quale consegna viene.", ingressi + f1_consegne, minuti=40)
        (f2 / "02-firme").mkdir(parents=True)
        (f2 / "02-firme" / "LEGGIMI.md").write_text(
            "Ogni autore di f1 scrive qui `<sigla>.md`: per ogni scheda nata dalle sue idee, «fedele» oppure «si perde: …».\n",
            encoding="utf-8")
        consegna(m, c, f2 / "03-triage", "arbitro", "f2", "TRIAGE.md",
                 "Assegna gli H# nella forma H-001, con la classe TESTARE, RIFORMULARE, APERTA o SMENTITA (solo con una prova), "
                 "e le prime tre in ordine. Il coordinatore sigilla il triage appena arriva.",
                 ingressi + [f2 / "01-traduzione" / "SCHEDE.md", f2 / "02-firme"], minuti=30)
        consegna(m, c, f2 / "04-torneo", "avversario", "f2", "TORNEO.md",
                 "Esegui il falsificatore di ogni H# TESTARE o APERTA del triage sigillato, al più cinque minuti ciascuno, "
                 "con l'esito atteso registrato prima. Una smentita vale per l'idea solo se la decide un controllo che non "
                 "condivide il prototipo; altrimenti l'H# torna RIFORMULARE.",
                 ingressi + [f2 / "03-triage" / "TRIAGE.md", f2 / "01-traduzione" / "SCHEDE.md"], minuti=40)
        consegna(m, c, f2 / "05-selezione", "arbitro", "f2", "SELEZIONE.md",
                 "Sugli esiti del torneo proponi al più tre H# più una radicale, con le priorità ordinali (informazione attesa, "
                 "costo, probabilità di un controesempio). Chiudi con la riga «Controfirma: arbitro».",
                 ingressi + [f2 / "03-triage" / "TRIAGE.md", f2 / "04-torneo" / "TORNEO.md"], minuti=20)
    (c / "f5").mkdir()
    if mappa:
        nascosta = dest / f".{c.name}.corsie"
        nascosta.mkdir(mode=0o700)
        (nascosta / "MAPPA.json").write_text(json.dumps(mappa, ensure_ascii=False, indent=1), encoding="utf-8")
        m["mappa"] = str(nascosta / "MAPPA.json")
    salva(c, m)
    print(f"Convocazione: {c}")
    print(f"Strategia {ns.strategia}, profilo {ns.profilo}, seme {seme}. Nessun agente lanciato.")
    print("Compila CONTRATTO.md, poi: cancello C f0 --note '…'")
    print("Consegne di f1:")
    for ruolo, v in m["f1"].items():
        print(f"  {ruolo} ({v['corsia']}): {v['cartella']}/TASK.md")
    if mappa:
        print(f"Mappa delle corsie (solo tua, non darla agli agenti): {m['mappa']}")


def fotografa(ns) -> None:
    c = Path(ns.C).resolve()
    m = carica(c)
    foto = {"ora": ora(), "file": {}}
    for v in m["f1"].values():
        for p in sorted(Path(v["cartella"]).rglob("*")):
            if p.is_file():
                s = p.stat()
                foto["file"][str(p)] = {"mtime": s.st_mtime, "letto_dopo": s.st_atime > s.st_mtime}
    (c / "FOTO.json").write_text(json.dumps(foto, indent=1), encoding="utf-8")
    letti = [p for p, v in foto["file"].items() if v["letto_dopo"] and not p.endswith("TASK.md")]
    print(f"Foto di {len(foto['file'])} file. Letti dopo l'ultima scrittura: {len(letti)}")
    for p in letti:
        print(f"  {p}")


def sigilla(ns) -> None:
    c = Path(ns.C).resolve()
    carica(c)
    with (c / "SIGILLI.jsonl").open("a", encoding="utf-8") as f:
        for nome in ns.file:
            p = Path(nome).resolve()
            if not p.is_file():
                raise Errore(f"non c'è {p}")
            f.write(json.dumps({"ora": ora(), "file": str(p), "sha256": sha(p), "byte": p.stat().st_size}) + "\n")
            print(f"Sigillato {p}")


def sigilli(c: Path) -> dict[str, dict]:
    p = c / "SIGILLI.jsonl"
    trovati = {}
    for riga in p.read_text(encoding="utf-8").splitlines() if p.exists() else []:
        s = json.loads(riga)
        trovati.setdefault(s["file"], s)
    return trovati


def ids_in(p: Path) -> list[str]:
    if not p.exists():
        return []
    return list(dict.fromkeys(f"H-{int(n):03d}" for n in ID.findall(p.read_text(encoding="utf-8"))))


def pieno(p: Path) -> bool:
    testo = p.read_text(encoding="utf-8", errors="replace") if p.is_file() else ""
    return p.is_file() and p.stat().st_size > 0 and DA_COMPILARE not in testo and DA_COMPILARE_EN not in testo


def cartelle_fase(c: Path, m: dict, fase: str) -> list[Path]:
    if fase == "f0":
        return [c / "f0"]
    if fase == "f1":
        return [Path(v["cartella"]) for v in m["f1"].values()] + ([c / "f1c"] if m["strategia"] == "completa" else [])
    if fase in ("f2", "f5"):
        return [c / fase]
    return [c / fase]


def impronte(c: Path, m: dict, fase: str) -> dict[str, str]:
    file = [c / "CONTRATTO.md"] if fase == "f0" else []
    for cartella in cartelle_fase(c, m, fase):
        file += sorted(p for p in cartella.rglob("*.md") if p.is_file())
    if fase.startswith("f3/") or fase.startswith("f4/"):
        file += sorted(p for p in cartella.rglob("*.json") if p.is_file() and not p.name.startswith("GATE_"))
    return {str(p): sha(p) for p in file}


def file_gate(c: Path, fase: str) -> Path:
    return c / f"GATE_{fase.replace('/', '_')}.json"


def valido(c: Path, m: dict, fase: str) -> bool:
    p = file_gate(c, fase)
    if not p.exists():
        return False
    g = json.loads(p.read_text(encoding="utf-8"))
    return g.get("impronte") == impronte(c, m, fase)


def condizioni(c: Path, m: dict, fase: str, non_consegnati: set[str]) -> list[str]:
    errori = []
    precedente = {"f1": "f0", "f2": "f1", "f5": "f2"}.get(fase)
    if fase.startswith("f3/"):
        precedente = "f2"
    elif fase.startswith("f4/"):
        precedente = "f3/" + fase[3:]
    if m["strategia"] in ("singolo", "ventaglio") and fase == "f5":
        precedente = "f1"
    if precedente and not valido(c, m, precedente):
        errori.append(f"il cancello {precedente} non è approvato o non è più valido")
    if fase == "f0":
        testo = (c / "CONTRATTO.md").read_text(encoding="utf-8")
        for campo in CAMPI_CONTRATTO:
            sezione = (re.search(rf"^## {campo}\n(.*?)(?=^## |\Z)", testo, re.S | re.M)
                       or re.search(rf"^## {CAMPI_EN[campo]}\n(.*?)(?=^## |\Z)", testo, re.S | re.M))
            if not sezione or not sezione.group(1).strip() or DA_COMPILARE in sezione.group(1) or DA_COMPILARE_EN in sezione.group(1):
                errori.append(f"CONTRATTO.md: «{campo}» da compilare")
    elif fase == "f1":
        mappa = json.loads(Path(m["mappa"]).read_text(encoding="utf-8")) if m.get("mappa") else {}
        ultima = 0.0
        for ruolo, v in m["f1"].items():
            uscita = Path(v["cartella"]) / "CONSEGNA.md"
            if ruolo in non_consegnati:
                continue
            if not pieno(uscita):
                errori.append(f"{ruolo}: manca la consegna {uscita}")
                continue
            ultima = max(ultima, uscita.stat().st_mtime)
            testo = uscita.read_text(encoding="utf-8", errors="replace")
            if ruolo in mappa:
                proprio = mappa[ruolo]["canarino"]
                if not testo.lstrip().startswith(f"Canarino: {proprio}"):
                    errori.append(f"{ruolo}: la consegna non comincia con il suo canarino")
                altri = {v2["canarino"] for r2, v2 in mappa.items() if v2["canarino"] != proprio}
                if any(a in testo for a in altri):
                    errori.append(f"{ruolo}: nella consegna c'è il canarino di un'altra corsia (contaminazione)")
        if mappa:
            foto = c / "FOTO.json"
            if not foto.exists():
                errori.append("manca la foto delle letture: fotografa C, prima di leggere")
            elif _iso(json.loads(foto.read_text(encoding="utf-8"))["ora"]) < ultima - 1:
                errori.append("la foto è anteriore all'ultima consegna: rifalla")
        if m["strategia"] == "completa" and not pieno(c / "f1c" / "arbitro" / "CONSOLIDAMENTO.md"):
            errori.append("manca il consolidamento dell'arbitro (f1c/arbitro/CONSOLIDAMENTO.md)")
    elif fase == "f2":
        f2 = c / "f2"
        for p in (f2 / "01-traduzione" / "SCHEDE.md", f2 / "03-triage" / "TRIAGE.md", f2 / "04-torneo" / "TORNEO.md",
                  f2 / "05-selezione" / "SELEZIONE.md"):
            if not pieno(p):
                errori.append(f"manca {p.relative_to(c)}")
        firme = [p for p in (f2 / "02-firme").glob("*.md") if p.name != "LEGGIMI.md"]
        if not firme:
            errori.append("nessuna firma degli autori in f2/02-firme")
        triage = f2 / "03-triage" / "TRIAGE.md"
        s = sigilli(c).get(str(triage))
        if triage.exists():
            if not s:
                errori.append("il triage non è sigillato: sigilla C f2/03-triage/TRIAGE.md")
            else:
                if s["sha256"] != sha(triage):
                    errori.append("il triage è cambiato dopo il sigillo")
                if any(p.stat().st_mtime > _iso(s["ora"]) + 1 for p in firme):
                    errori.append("una firma è arrivata dopo il sigillo del triage")
                torneo = f2 / "04-torneo" / "TORNEO.md"
                if torneo.exists() and torneo.stat().st_mtime < _iso(s["ora"]):
                    errori.append("il torneo è anteriore al sigillo del triage")
        selezione = f2 / "05-selezione" / "SELEZIONE.md"
        if selezione.exists():
            fuori = set(ids_in(selezione)) - set(ids_in(triage))
            if fuori:
                errori.append(f"la selezione nomina H# che il triage non ha: {', '.join(sorted(fuori))}")
            if "Controfirma: arbitro" not in selezione.read_text(encoding="utf-8"):
                errori.append("la selezione non ha la riga «Controfirma: arbitro»")
    elif fase.startswith("f3/") or fase.startswith("f4/"):
        h = fase[3:]
        if h not in m["selezionate"] + ([m["radicale"]] if m["radicale"] else []):
            errori.append(f"{h} non è selezionata")
        if (c / "f3" / h / "CHIUSURA_ANTICIPATA.json").exists():
            errori.append(f"il ramo {h} è chiuso in anticipo: niente G3 né G4")
        cartella = c / fase
        if fase.startswith("f3/"):
            for nome in ("SOLUZIONE.md", "VERIFICA.md", "PIANO_MISURE.md", "ATTACCO.md", "PREVISIONI.md"):
                if not any(pieno(p) for p in cartella.rglob(nome)):
                    errori.append(f"{fase}: manca {nome}")
            for p in cartella.rglob("PREVISIONI.md"):
                if not re.search(r"^decide: (sì|si|no)\s*$", p.read_text(encoding="utf-8"), re.M):
                    errori.append(f"{p.relative_to(c)}: manca la riga «decide: sì» o «decide: no»")
        else:
            for nome in ("CONTROPROVE.md", "VERDETTO.md"):
                if not any(pieno(p) for p in cartella.rglob(nome)):
                    errori.append(f"{fase}: manca {nome}")
            sig = sigilli(c)
            controprove = [p for p in cartella.rglob("CONTROPROVE.md")]
            for p in cartella.rglob("PREVISIONI.md"):
                s = sig.get(str(p))
                if not s:
                    errori.append(f"{p.relative_to(c)} nata in f4 non è sigillata")
                elif sha(p) != s["sha256"] and not _solo_coda(p, s):
                    errori.append(f"{p.relative_to(c)} è cambiata dopo il sigillo, non solo in coda")
                elif any(q.stat().st_mtime < _iso(s["ora"]) for q in controprove):
                    errori.append(f"{p.relative_to(c)} è sigillata dopo le controprove")
            dossier = c / "f3" / h / f"{h}.md"
            if dossier.exists():
                vuoti = [r for r in dossier.read_text(encoding="utf-8").splitlines() if re.match(r"^- [^|]*:\s*$", r)]
                if vuoti:
                    errori.append(f"il dossier {h} ha {len(vuoti)} campi vuoti (si scrive «manca»)")
            else:
                errori.append(f"manca il dossier {dossier.relative_to(c)}")
    elif fase == "f5":
        chiusura = c / "f5" / "CHIUSURA.md"
        if not pieno(chiusura):
            errori.append("manca f5/CHIUSURA.md dell'arbitro")
        elif not re.search(r"^Esito: (chiuso|non chiuso)\b", chiusura.read_text(encoding="utf-8"), re.M):
            errori.append("CHIUSURA.md senza la riga «Esito: chiuso» o «Esito: non chiuso»")
        if m["strategia"] not in ("singolo", "ventaglio"):
            rami = m["selezionate"] + ([m["radicale"]] if m["radicale"] else [])
            provati = [h for h in rami if valido(c, m, f"f4/{h}")]
            aperti = [h for h in rami if h not in provati and not (c / "f3" / h / "CHIUSURA_ANTICIPATA.json").exists()]
            if aperti:
                errori.append(f"rami senza G4 valido né chiusura anticipata: {', '.join(aperti)}")
            if rami and not provati:
                errori.append("nessuna H# provata: il ciclo non si chiude con un G5")
    return errori


def _iso(s: str) -> float:
    return datetime.datetime.fromisoformat(s).timestamp()


def _solo_coda(p: Path, s: dict) -> bool:
    """Il sigillo vale ancora se al file si è solo aggiunto in coda: i primi byte sono quelli sigillati."""
    dati = p.read_bytes()
    byte = s.get("byte")
    return byte is not None and len(dati) >= byte and hashlib.sha256(dati[:byte]).hexdigest() == s["sha256"]


def cancello(ns) -> None:
    c = Path(ns.C).resolve()
    m = carica(c)
    fase = ns.fase
    if not re.fullmatch(r"f[0125]|f[34]/H-\d{3}", fase):
        raise Errore(f"fase sconosciuta: {fase}")
    non = {r.strip() for r in (ns.non_consegnati or "").split(",") if r.strip()}
    errori = condizioni(c, m, fase, non)
    if errori:
        print(f"Cancello {fase} RIFIUTATO:")
        for e in errori:
            print(f"  - {e}")
        sys.exit(1)
    if ns.verifica:
        print(f"Cancello {fase}: le condizioni reggono (verifica, niente scritto)")
        return
    g = {"fase": fase, "ora": ora(), "note": ns.note, "non_consegnati": sorted(non), "impronte": impronte(c, m, fase)}
    file_gate(c, fase).write_text(json.dumps(g, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"Cancello {fase} approvato ({len(g['impronte'])} file legati)")


def seleziona(ns) -> None:
    c = Path(ns.C).resolve()
    m = carica(c)
    if m["strategia"] in ("singolo", "ventaglio"):
        raise Errore("nel singolo non ci sono ipotesi da selezionare")
    if not valido(c, m, "f2"):
        raise Errore("il cancello f2 non è approvato o non è più valido")
    scelte = [norm_id(h) for h in ns.ipotesi]
    radicale = norm_id(ns.radicale) if ns.radicale else None
    if len(scelte) > 3:
        raise Errore("al più tre H# più una radicale")
    ammesse = set(ids_in(c / "f2" / "03-triage" / "TRIAGE.md")) & set(ids_in(c / "f2" / "05-selezione" / "SELEZIONE.md"))
    for h in scelte + ([radicale] if radicale else []):
        if h not in ammesse:
            raise Errore(f"{h} non è nel triage e nella selezione controfirmata")
    cat = catalogo()
    prof = cat["profili"][m["profilo"]]
    if ns.responsabile and ns.responsabile not in {r["sigla"] for r in cat["ruoli"]}:
        raise Errore(f"ruolo sconosciuto: {ns.responsabile}")
    modello = (BASE / "SCHEDA_IPOTESI.md").read_text(encoding="utf-8")
    ingressi_base = [c / "CONTRATTO.md", c / "f2" / "01-traduzione" / "SCHEDE.md", c / "f2" / "03-triage" / "TRIAGE.md",
                     c / "f2" / "04-torneo" / "TORNEO.md"]
    for h in scelte + ([radicale] if radicale else []):
        f3, f4 = c / "f3" / h, c / "f4" / h
        f3.mkdir(parents=True, exist_ok=True)
        (f3 / f"{h}.md").write_text(modello.replace("H-000", h), encoding="utf-8")
        responsabile = ns.responsabile or prof["f3"][0]
        verifica = next((r for r in prof["f3"][1:] if r not in ("avversario", "metrologo", responsabile)), "logico")
        consegna(m, c, f3 / f"01-{responsabile}", responsabile, "f3", "SOLUZIONE.md",
                 f"Sei il responsabile di {h}. Scrivi la soluzione: passi, invarianti, costo, «dipende da», «invalidata se "
                 "cambia». Le previsioni con la soglia in PREVISIONI.md, con la riga «decide: sì» o «decide: no».",
                 ingressi_base, minuti=LIMITE_RAMO, h=h)
        consegna(m, c, f3 / f"02-{verifica}", verifica, "f3", "VERIFICA.md",
                 f"Scrivi la prova o la verifica di {h}, dopo SOLUZIONE.md del responsabile: che cosa la rende corretta, con "
                 "quali ipotesi, e come la si controlla.", ingressi_base + [f3 / f"01-{responsabile}" / "SOLUZIONE.md"],
                 minuti=LIMITE_RAMO, h=h)
        consegna(m, c, f3 / "03-metrologo", "metrologo", "f3", "PIANO_MISURE.md",
                 f"Il piano delle misure di {h}: che cosa si misura, con quale soglia, prima delle prove. Se non servono misure, "
                 "scrivilo con il perché.", ingressi_base + [f3 / f"01-{responsabile}" / "SOLUZIONE.md"], minuti=30, h=h)
        consegna(m, c, f3 / "04-avversario", "avversario", "f3", "ATTACCO.md",
                 f"L'attacco a {h}: i casi che dovrebbero romperla, con le previsioni prima.",
                 ingressi_base + [f3 / f"01-{responsabile}" / "SOLUZIONE.md"], minuti=30, h=h)
        consegna(m, c, f4 / "01-avversario", "avversario", "f4", "CONTROPROVE.md",
                 f"Esegui le controprove di {h}, dalla più economica: prima le falsificazioni, poi la correttezza, poi il controllo "
                 "dissimile. Le previsioni nate ora vanno sigillate dal coordinatore prima delle prove.",
                 ingressi_base + [f3], minuti=LIMITE_RAMO, h=h)
        consegna(m, c, f4 / "02-debugger", "debugger", "f4", "DIFETTI.md",
                 f"Le anomalie delle controprove di {h} e i difetti nascosti, ciascuno con la causa provata o «non spiegata». "
                 "Se non ci sono anomalie, elenca i controlli fatti.", ingressi_base + [f3, f4 / "01-avversario"], h=h)
        for i, ruolo in enumerate([r for r in prof["f4"] if r not in ("avversario", "debugger")], start=3):
            consegna(m, c, f4 / f"{i:02d}-{ruolo}", ruolo, "f4", "MISURE.md",
                     f"Il tuo contributo alle prove di {h}, sul piano delle misure, dopo le controprove.",
                     ingressi_base + [f3, f4 / "01-avversario"], h=h)
        consegna(m, c, f4 / "09-arbitro", "arbitro", "f4", "VERDETTO.md",
                 f"Il verdetto di {h} per proprietà (correttezza, completezza, efficacia, costo), e il dossier "
                 f"{f3 / (h + '.md')} completato campo per campo («manca» dove manca).", ingressi_base + [f3, f4], minuti=30, h=h)
    m["selezionate"], m["radicale"] = scelte, radicale
    salva(c, m)
    consegna(m, c, c / "f5" / "01-arbitro", "arbitro", "f5", "CHIUSURA.md",
             "La chiusura: almeno una H# provata, nessuna contraddizione aperta su una conclusione adottata, previsioni risolte o "
             "dichiarate non risolte con la prova che le deciderebbe, le quattro verifiche dei risultati fondanti. Scrivi anche "
             f"{c / 'f5' / 'CHIUSURA.md'} con la riga «Esito: chiuso» o «Esito: non chiuso», e al più tre decisioni per l'utente.",
             [c / "CONTRATTO.md", c / "f3", c / "f4"], minuti=30)
    print(f"Rami aperti: {', '.join(scelte + ([radicale] if radicale else []))}")


def chiudi_ramo(ns) -> None:
    c = Path(ns.C).resolve()
    m = carica(c)
    h = norm_id(ns.ipotesi)
    if h not in m["selezionate"] + ([m["radicale"]] if m["radicale"] else []):
        raise Errore(f"{h} non è selezionata")
    if valido(c, m, f"f3/{h}"):
        raise Errore(f"{h} ha già un G3: la chiusura anticipata vale solo prima")
    p = c / "f3" / h / "CHIUSURA_ANTICIPATA.json"
    if p.exists():
        raise Errore(f"{h} è già chiusa")
    p.write_text(json.dumps({"ora": ora(), "ipotesi": h, "motivo": ns.motivo, "stato": "non risolto dichiarato"},
                            ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"{h} chiusa in anticipo: non risolto dichiarato")


def stato(ns) -> None:
    c = Path(ns.C).resolve()
    m = carica(c)
    print(f"{m['nome']}: strategia {m['strategia']}, profilo {m['profilo']}")
    fasi = ["f0", "f1"] + ([] if m["strategia"] in ("singolo", "ventaglio") else ["f2"])
    for h in m["selezionate"] + ([m["radicale"]] if m["radicale"] else []):
        fasi += [f"f3/{h}", f"f4/{h}"]
    if m["strategia"] not in ("singolo", "ventaglio"):
        fasi.append("f5")
    for fase in fasi:
        if fase.startswith("f3/") and (c / fase / "CHIUSURA_ANTICIPATA.json").exists():
            print(f"  {fase}: CHIUSO IN ANTICIPO")
            continue
        g = file_gate(c, fase)
        if not g.exists():
            print(f"  {fase}: da approvare")
        else:
            print(f"  {fase}: {'approvato' if valido(c, m, fase) else 'NON PIÙ VALIDO (file cambiati)'}")


def main() -> None:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sp = p.add_subparsers(dest="comando", required=True)
    q = sp.add_parser("ruoli")
    q.add_argument("--domanda")
    q = sp.add_parser("prepara")
    q.add_argument("--nome", required=True)
    q.add_argument("--strategia", required=True, choices=STRATEGIE)
    q.add_argument("--profilo", required=True)
    q.add_argument("--domanda", required=True)
    q.add_argument("--ruoli")
    q.add_argument("--dest", default=".sciame")
    q.add_argument("--seme", type=int)
    q.add_argument("--n", type=int, help="ventaglio: il numero totale di agenti, da 2 a 16")
    q.add_argument("--forma", choices=FORME, help="ventaglio: fette, gara o mista")
    q.add_argument("--regola", choices=REGOLE, help="ventaglio, gara o mista: la regola di scelta dichiarata prima")
    q = sp.add_parser("fotografa")
    q.add_argument("C")
    q = sp.add_parser("cancello")
    q.add_argument("C")
    q.add_argument("fase")
    q.add_argument("--note", required=True)
    q.add_argument("--non-consegnati")
    q.add_argument("--verifica", action="store_true")
    q = sp.add_parser("sigilla")
    q.add_argument("C")
    q.add_argument("file", nargs="+")
    q = sp.add_parser("seleziona")
    q.add_argument("C")
    q.add_argument("ipotesi", nargs="+")
    q.add_argument("--radicale")
    q.add_argument("--responsabile", metavar="SIGLA")
    q = sp.add_parser("chiudi-ramo")
    q.add_argument("C")
    q.add_argument("ipotesi")
    q.add_argument("--motivo", required=True)
    q = sp.add_parser("stato")
    q.add_argument("C")
    ns = p.parse_args()
    comandi = {"ruoli": ruoli, "prepara": prepara, "fotografa": fotografa, "cancello": cancello, "sigilla": sigilla, "seleziona": seleziona,
               "chiudi-ramo": chiudi_ramo, "stato": stato}
    try:
        comandi[ns.comando](ns)
    except (Errore, OSError, ValueError) as e:
        print(f"convoca: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
#==== sciame.sh: file motore/genera.py ====
#!/usr/bin/env python3
"""Il generatore dello sciame 4.0: dal database, dai documenti della lingua e dagli override locali genera, nella
radice del progetto, il catalogo, gli agenti, le skill e i documenti nella lingua scelta.

Le fonti:
- `<sciame>/db/`: il database unico dei professionisti e dei sottoprofessionisti;
- `<sciame>/documenti/<lingua>/`: i documenti (PREAMBOLO, PIPELINE, ISTRUZIONI_COORDINATORE, GIURIA, AMBIENTE,
  SCHEDA_IPOTESI, README, la testa di AGENTI);
- `<sciame>/i18n/<lingua>.json`: i testi del generatore e dei comandi;
- gli override locali (`<sciame>/locale/AGENTI.md`, o la cartella di `config.json`): una scheda locale vale sempre al
  posto del ruolo generico con la stessa sigla, e un ruolo solo locale si aggiunge.

Ciò che scrive porta sempre la nota `GENERATO`: un file senza la nota (per esempio un agente del progetto) non si
tocca né si cancella mai. Si usa da `motore/sciame.py`; solo libreria standard.
"""
from __future__ import annotations

import hashlib
import json
import re
import sys
from pathlib import Path

QUI = Path(__file__).resolve().parent
sys.path.insert(0, str(QUI))
import professionisti as P  # noqa: E402
import percorsi as S  # noqa: E402

VERSIONE = "4.0"
STRATEGIE = ("singolo", "ventaglio", "classica", "giuria", "giuria-leggera", "completa", "plenaria", "esperto", "auto")
SKILL = {"auto": "sciame", **{s: f"sciame-{s}" for s in STRATEGIE if s != "auto"}}
# Le strategie costose si avviano solo per richiesta esplicita dell'utente.
SOLO_UTENTE = {"completa", "plenaria"}
DOCUMENTI = ("PREAMBOLO.md", "PIPELINE.md", "ISTRUZIONI_COORDINATORE.md", "GIURIA.md", "AMBIENTE.md",
             "SCHEDA_IPOTESI.md", "README.md")
BLOCCO = re.compile(r"<!-- ([a-z-]+(?::[a-z-]+)?) -->\n(.*?)\n<!-- /\1 -->", re.S)
GENERATO = S.GENERATO
MODELLO = re.compile(r"^[A-Za-z0-9._:-]{1,64}$")
CARTELLA_AGENTI = ".claude/agents"
CARTELLA_SKILL = ".claude/skills"


class Errore(Exception):
    pass


def i18n(sciame: Path, lingua: str) -> dict:
    base = json.loads((sciame / "i18n" / "it.json").read_text(encoding="utf-8"))
    p = sciame / "i18n" / f"{lingua}.json"
    if p.is_file():
        base.update(json.loads(p.read_text(encoding="utf-8")))
    return base


def lingue_disponibili(sciame: Path) -> list[str]:
    doc = {p.name for p in (sciame / "documenti").iterdir() if p.is_dir()} if (sciame / "documenti").is_dir() else set()
    return sorted(l for l in doc if (sciame / "i18n" / f"{l}.json").is_file())


def config(radice: Path) -> dict:
    p = radice / ".sciame" / "config.json"
    if p.is_file():
        return json.loads(p.read_text(encoding="utf-8"))
    return {}


def blocchi(testo: str) -> dict[str, str]:
    return {m.group(1): m.group(2).strip() for m in BLOCCO.finditer(testo)}


def profili(testo: str, sigle: set[str]) -> dict[str, dict]:
    trovati = {}
    for riga in testo.splitlines():
        m = re.match(r"^\| `([a-z-]+)` \|(.*)\|\s*$", riga)
        if not m:
            continue
        celle = [c.strip() for c in m.group(2).split("|")]
        if len(celle) != 6:
            raise Errore(f"profilo {m.group(1)}: {len(celle)} colonne invece di 6")
        per, a, b, traduce, f3, f4 = celle

        def ruoli_di(cella):
            nomi = re.findall(r"[a-z]+(?:-[a-z]+)*", cella)
            return [n for n in dict.fromkeys(nomi) if n in sigle]
        if m.group(1) in trovati:
            raise Errore(f"due profili con il nome {m.group(1)}")
        trovati[m.group(1)] = {"per": per, "A": ruoli_di(a), "B": ruoli_di(b), "traduce": ruoli_di(traduce),
                               "f3": ruoli_di(f3), "f4": ruoli_di(f4)}
    if "generale" not in trovati:
        raise Errore("manca il profilo generale")
    return trovati


def catalogo(sciame: Path, radice: Path, lingua: str) -> dict:
    """Tutto ciò che serve a generare: ruoli (generici e locali, con la priorità ai locali), profili, testi."""
    sciame, radice = Path(sciame), Path(radice)
    cfg = config(radice)
    d = P.carica(sciame / "db")
    errori = P.valida(d, [lingua])
    if errori:
        raise Errore("database non valido:\n  " + "\n  ".join(errori[:20]))
    t = i18n(sciame, lingua)
    cartella_doc = sciame / "documenti" / lingua
    if not cartella_doc.is_dir():
        raise Errore(f"lingua «{lingua}» senza documenti: le lingue sono {', '.join(lingue_disponibili(sciame))}")
    testi = {n: (cartella_doc / n).read_text(encoding="utf-8") for n in DOCUMENTI if (cartella_doc / n).is_file()}
    for n in DOCUMENTI:
        if n not in testi:
            raise Errore(f"documenti/{lingua}/{n} manca")
    pre, pipe, istr, amb = (blocchi(testi[n]) for n in ("PREAMBOLO.md", "PIPELINE.md", "ISTRUZIONI_COORDINATORE.md",
                                                         "AMBIENTE.md"))
    for chiave, dove in (("regole-in-breve", pre), ("profili", pipe), ("consegna", pipe), ("coordinatore", istr),
                         ("claude-code", istr), ("ambiente:progetto", istr), ("ambiente", amb)):
        if chiave not in dove:
            raise Errore(f"documenti/{lingua}: manca il blocco «{chiave}»")
    for s in STRATEGIE:
        if f"strategia:{s}" not in pipe:
            raise Errore(f"documenti/{lingua}/PIPELINE.md: manca il blocco strategia:{s}")
    file_locale = S.file_agenti_locale(radice, sciame)
    locali = P.schede_locali(file_locale)
    regole = pre["regole-in-breve"]
    ruoli = []
    for v in P.ordinate(d):
        tv = P.testo(v, lingua)
        r = {"n": v["numero"], "sigla": v["sigla"], "nome": tv["nome"], "nucleo": v["nucleo"], "tipo": v["tipo"],
             "genitore": v.get("genitore"), "breve": tv["breve"], "parole": tv["parole"],
             "scheda": P.scheda(d, v, lingua).strip(), "origine": "generico"}
        if v["sigla"] in locali:
            loc = locali.pop(v["sigla"])
            r.update({"nome": loc["nome"], "breve": loc["breve"] or r["breve"], "scheda": loc["scheda"],
                      "origine": "locale"})
        ruoli.append(r)
    for sigla, loc in locali.items():  # i ruoli solo locali
        ruoli.append({"n": f"L{loc['numero']}", "sigla": sigla, "nome": loc["nome"], "nucleo": "locale",
                      "tipo": "professionista", "genitore": None, "breve": loc["breve"], "parole": [],
                      "scheda": loc["scheda"], "origine": "solo-locale"})
    sigle = {r["sigla"] for r in ruoli}
    nomi_nuclei = {n["id"]: P.nome_nucleo(d, n["id"], lingua) for n in d["nuclei"]}
    nomi_nuclei["locale"] = t["nucleo_locale"]
    for r in ruoli:
        r["descrizione"] = descrizione(dict(r, nucleo=nomi_nuclei.get(r["nucleo"], r["nucleo"]).lower()), t)
        r["prompt"] = prompt_ruolo(r, regole, t, lingua)
    tabella = profili(pipe["profili"], sigle)
    impronta = hashlib.sha256(json.dumps([d["voci"], d["nuclei"], sorted(testi.items()),
                                          [(r["sigla"], r["scheda"]) for r in ruoli if r["origine"] != "generico"]],
                                         ensure_ascii=False, sort_keys=True).encode()).hexdigest()
    nuclei = [{"id": n["id"], "nome": P.nome_nucleo(d, n["id"], lingua)} for n in d["nuclei"]]
    if any(r["nucleo"] == "locale" for r in ruoli):
        nuclei.append({"id": "locale", "nome": t["nucleo_locale"]})
    for chi, m in cfg.get("modelli", {}).items():
        if not MODELLO.match(str(m)) or not re.match(r"^[a-z0-9*][a-z0-9-]*$", str(chi)):
            raise Errore(f"modelli: «{chi}={m}» non è un nome di ruolo e di modello valido")
    try:
        cartella = sciame.resolve().relative_to(radice.resolve()).as_posix()
    except ValueError:
        cartella = "sciame"
    try:
        loc = S.cartella_locale(radice, sciame).resolve().relative_to(radice.resolve()).as_posix()
        loc_file = file_locale.resolve().relative_to(radice.resolve()).as_posix()
    except ValueError:
        loc, loc_file = f"{cartella}/locale", f"{cartella}/locale/AGENTI.md"
    return {
        "cartella": cartella, "cartella_locale": loc, "file_locale": loc_file,
        "versione": VERSIONE, "lingua": lingua, "impronta": impronta, "nuclei": nuclei, "ruoli": ruoli,
        "profili": tabella, "modelli": cfg.get("modelli", {}), "gestiti_dal_progetto": cfg.get("gestiti_dal_progetto", False),
        "testi": {"regole": regole, "consegna": pipe["consegna"], "coordinatore": istr["coordinatore"],
                  "strategie": {s: pipe[f"strategia:{s}"] for s in STRATEGIE}, "profili": pipe["profili"],
                  "claude_code": istr["claude-code"], "ambiente": amb["ambiente"],
                  "ambienti": {"progetto": istr["ambiente:progetto"]},
                  "ambienti_agenti": {"progetto": t["ambiente_agente"], "senza-strumenti": t["ambiente_senza_strumenti"]}},
        "documenti": testi, "testa_agenti": t["testa_agenti"], "i18n": t,
    }


def descrizione(r: dict, t: dict) -> str:
    tipo = t["sotto_di"].format(genitore=r["genitore"]) if r["tipo"] == "sottoprofessionista" else ""
    return f"{r['nome']}: {r['breve']}{tipo} {t['descrizione_coda'].format(nucleo=r['nucleo'])}"


def prompt_ruolo(r: dict, regole: str, t: dict, lingua: str) -> str:
    return t["prompt_ruolo"].format(nome=r["nome"], n=r["n"], breve=r["breve"]) + f"\n\n{regole}\n\n## {t['la_tua_scheda']}\n\n{r['scheda']}\n"


def adatta(dati: dict, testo: str) -> str:
    """I testi parlano di `sciame/` e di `sciame/locale/`: in un'installazione in un'altra cartella diventano quelle vere."""
    if dati.get("cartella", "sciame") == "sciame" and dati.get("cartella_locale", "sciame/locale") == "sciame/locale":
        return testo
    testo = testo.replace("sciame/locale/AGENTI.md", "\0LOCALEF\0").replace("sciame/locale/", "\0LOCALED\0")
    testo = re.sub(r"(?<![A-Za-z0-9_.-])sciame/(?=[A-Za-z_.`])", dati["cartella"] + "/", testo)
    return testo.replace("\0LOCALEF\0", dati["file_locale"]).replace("\0LOCALED\0", dati["cartella_locale"] + "/")


def modello(dati: dict, r: dict) -> str:
    m = dati["modelli"]
    return m.get(r["sigla"]) or m.get(r["nucleo"]) or m.get("*") or "inherit"


def agente(dati: dict, r: dict) -> str:
    t = dati["i18n"]
    nota = S.nota(t["nota_agente"].format(n=r["n"], nome=" ".join(r["nome"].split())))
    return (f"---\nname: sciame-{r['sigla']}\ndescription: {json.dumps(r['descrizione'], ensure_ascii=False)}\n"
            f"model: {modello(dati, r)}\n---\n\n{nota}\n\n"
            + adatta(dati, f"{r['prompt']}\n{dati['testi']['ambienti_agenti']['progetto']}\n"))


def indice_ruoli(dati: dict) -> str:
    t = dati["i18n"]
    nomi = {n["id"]: n["nome"] for n in dati["nuclei"]}
    righe = [f"## {t['i_ruoli']}", "", t["indice_spiega"], "", t["indice_testa"], "|---|---|---|---|---|"]
    for r in dati["ruoli"]:
        tipo = t["tipo_sotto"].format(genitore=r["genitore"]) if r["tipo"] == "sottoprofessionista" else t["tipo_prof"]
        if r["origine"] != "generico":
            tipo += f" ({t['origine_' + r['origine'].replace('-', '_')]})"
        righe.append(f"| `sciame-{r['sigla']}` | {r['nome']} | {nomi.get(r['nucleo'], r['nucleo']).lower()} | {tipo} | "
                     f"{', '.join(r['parole'])} |")
    return "\n".join(righe)


def skill(dati: dict, strategia: str) -> str:
    t, x = dati["i18n"], dati["testi"]
    testa = ["---", f"name: {SKILL[strategia]}", f"description: {json.dumps(t['skill_descrizione'][strategia], ensure_ascii=False)}",
             f"argument-hint: {json.dumps(t['skill_argomenti'], ensure_ascii=False)}"]
    if strategia in SOLO_UTENTE:
        testa.append("disable-model-invocation: true")
    testa.append("---")
    parti = ["\n".join(testa), S.nota(t["nota_skill"]), f"# {t['skill_titolo'][strategia]}",
             x["coordinatore"], x["consegna"], x["ambiente"]]
    if strategia == "auto":
        parti += [t["auto_premessa"]] + [x["strategie"][s] for s in ("auto", "singolo", "ventaglio", "classica",
                                                                       "giuria", "giuria-leggera", "completa", "plenaria",
                                                                       "esperto")]
    elif strategia == "completa":
        parti += [t["completa_premessa"], x["strategie"]["completa"], x["strategie"]["classica"]]
    elif strategia == "plenaria":
        parti += [t["plenaria_premessa"], x["strategie"]["plenaria"], x["strategie"]["completa"],
                  x["strategie"]["giuria"]]
    else:
        parti += [t["strategia_e"].format(strategia=strategia), x["strategie"][strategia]]
    if strategia not in ("singolo", "esperto"):
        parti.append(x["profili"])
    parti += [indice_ruoli(dati), x["claude_code"], x["ambienti"]["progetto"], t["la_richiesta"]]
    testo = "\n\n".join(parti) + "\n"
    testa_yaml, _, corpo = testo.partition("\n---\n")
    return testa_yaml + "\n---\n" + adatta(dati, corpo)


def file_generati(dati: dict) -> dict[str, str]:
    """Percorso relativo alla radice del progetto → testo. Gli agenti dei ruoli che il progetto genera da sé (i suoi
    override, se `gestiti_dal_progetto`) non si scrivono."""
    file = {}
    for r in dati["ruoli"]:
        if dati["gestiti_dal_progetto"] and r["origine"] != "generico":
            continue
        file[f"{CARTELLA_AGENTI}/sciame-{r['sigla']}.md"] = agente(dati, r)
    for s, nome in SKILL.items():
        file[f"{CARTELLA_SKILL}/{nome}/SKILL.md"] = skill(dati, s)
    return file


def file_sciame(dati: dict) -> dict[str, str]:
    """I file generati dentro la cartella dello sciame: catalogo, versione, documenti nella lingua, AGENTI.md."""
    ruoli_cat = [{k: v for k, v in r.items()} for r in dati["ruoli"]]
    cat = {k: v for k, v in dati.items() if k not in ("documenti", "i18n", "testa_agenti", "ruoli")}
    cat["ruoli"] = ruoli_cat
    out = {"catalogo.json": json.dumps(cat, ensure_ascii=False, indent=1) + "\n",
           "VERSIONE": f"{dati['versione']} {dati['impronta'][:12]} {dati['lingua']}\n"}
    nota = S.nota(dati["i18n"]["nota_documento"]) + "\n"
    for n, testo in dati["documenti"].items():
        out[n] = nota + adatta(dati, testo)
    return out


def agenti_md(sciame: Path, dati: dict) -> str:
    d = P.carica(Path(sciame) / "db")
    return S.nota(dati["i18n"]["nota_documento"]) + "\n" + adatta(dati, P.agenti_md(d, dati["lingua"], dati["testa_agenti"]))


generato = S.generato


def _sicuro(base: Path, relativo: str) -> Path:
    try:
        return S.senza_collegamenti(base, Path(base) / relativo)
    except S.Errore as e:
        raise Errore(str(e))


def scrivi(sciame: Path, radice: Path, dati: dict, sostituibili: frozenset = frozenset()) -> list[str]:
    """Scrive ciò che genera. Non sovrascrive mai un file che non porta la nota GENERATO; toglie solo i propri file
    che non servono più."""
    sciame, radice = Path(sciame), Path(radice)
    fatti, saltati = [], []
    file = file_generati(dati)
    for relativo, testo in file.items():
        p = _sicuro(radice, relativo)
        if p.exists() and not generato(p) and relativo not in sostituibili:
            saltati.append(relativo)
            continue
        S.scrivi(radice, p, testo)
        fatti.append(relativo)
    for p in sorted((radice / CARTELLA_AGENTI).glob("sciame-*.md")) if (radice / CARTELLA_AGENTI).is_dir() else []:
        rel = p.relative_to(radice).as_posix()
        if rel not in file and (generato(p) or rel in sostituibili):
            S.togli(radice, p)
            fatti.append(f"-{rel}")
    for relativo, testo in {**file_sciame(dati), "AGENTI.md": agenti_md(sciame, dati)}.items():
        p = _sicuro(sciame, relativo)
        if p.exists() and not generato(p) and relativo not in ("catalogo.json", "VERSIONE") and f"sciame/{relativo}" not in sostituibili:
            saltati.append(f"{sciame.name}/{relativo}")
            continue
        S.scrivi(sciame, p, testo)
    return fatti + [f"saltato (non generato dallo sciame): {s}" for s in saltati]


def controlla(sciame: Path, radice: Path, dati: dict) -> list[str]:
    diversi = []
    for relativo, testo in file_generati(dati).items():
        p = radice / relativo
        if not p.is_file():
            diversi.append(f"manca {relativo}")
        elif generato(p) and p.read_text(encoding="utf-8") != testo:
            diversi.append(f"diverso {relativo}")
    for relativo, testo in {**file_sciame(dati), "AGENTI.md": agenti_md(sciame, dati)}.items():
        p = Path(sciame) / relativo
        if p.is_file() and (generato(p) or relativo in ("catalogo.json", "VERSIONE")) and p.read_text(encoding="utf-8") != testo:
            diversi.append(f"diverso {Path(sciame).name}/{relativo}")
    return diversi


def sostituibili_31(sciame: Path, radice: Path) -> frozenset:
    """I file di un'installazione 3.x da sostituire: gli agenti delle sigle del suo catalogo con la nota della 3.x, le
    sue quattro skill e i suoi documenti. Mai un file per la sola nota: la stessa nota la usano anche altri generatori."""
    v = Path(sciame) / "VERSIONE"
    if not v.is_file() or not v.read_text(encoding="utf-8").startswith("3."):
        return frozenset()
    try:
        cat = json.loads((Path(sciame) / "catalogo.json").read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return frozenset()
    out = set()
    for r in cat.get("ruoli", []):
        rel = f"{CARTELLA_AGENTI}/sciame-{r['sigla']}.md"
        p = Path(radice) / rel
        if p.is_file() and "Generato da sciame/genera_agenti.py dalla scheda" in p.read_text(encoding="utf-8")[:800] \
                and r.get("prompt", "")[:80] in p.read_text(encoding="utf-8"):
            out.add(rel)
    for nome in ("sciame", "sciame-singolo", "sciame-classica", "sciame-completa"):
        rel = f"{CARTELLA_SKILL}/{nome}/SKILL.md"
        p = Path(radice) / rel
        if p.is_file() and "Generato da sciame/genera_agenti.py dai documenti di sciame/" in p.read_text(encoding="utf-8")[:800]:
            out.add(rel)
    for n in ("AGENTI.md", "PREAMBOLO.md", "PIPELINE.md", "ISTRUZIONI_COORDINATORE.md", "SCHEDA_IPOTESI.md", "README.md"):
        out.add(f"sciame/{n}")
    return frozenset(out)


def togli(radice: Path) -> list[str]:
    tolti = []
    for p in sorted((radice / CARTELLA_AGENTI).glob("sciame-*.md")) if (radice / CARTELLA_AGENTI).is_dir() else []:
        if generato(p):
            S.togli(radice, p)
            tolti.append(p.relative_to(radice).as_posix())
    for nome in SKILL.values():
        p = radice / CARTELLA_SKILL / nome / "SKILL.md"
        if generato(p):
            S.togli(radice, p)
            tolti.append(p.relative_to(radice).as_posix())
            if not any(p.parent.iterdir()):
                p.parent.rmdir()
    return tolti
#==== sciame.sh: file motore/genera_agenti.py ====
#!/usr/bin/env python3
"""Sciame 4.0: il comando di sempre, `python3 -I sciame/genera_agenti.py`, con le opzioni della 3.x.

    python3 -I sciame/genera_agenti.py                    # rigenera tutto nel progetto
    python3 -I sciame/genera_agenti.py --controlla        # esce con 1 se qualcosa non è allineato alle fonti
    python3 -I sciame/genera_agenti.py --installa RADICE  # installa lo sciame in un altro progetto
    python3 -I sciame/genera_agenti.py --istruzioni       # il paragrafo dello sciame in CLAUDE.md
    python3 -I sciame/genera_agenti.py --togli-istruzioni
    python3 -I sciame/genera_agenti.py --togli            # toglie agenti e skill generati
    python3 -I sciame/genera_agenti.py --elenco           # i ruoli
Il lavoro lo fa sciame/motore/sciame.py.
"""
import subprocess
import sys
from pathlib import Path

QUI = Path(__file__).resolve().parent
SCIAME = QUI.parent if QUI.name == "motore" else QUI
MOTORE = SCIAME / "motore" / "sciame.py"


def lancia(*arg):
    sys.exit(subprocess.run([sys.executable, "-I", str(MOTORE), "--sciame", str(SCIAME), *arg]).returncode)


a = sys.argv[1:]
if not a:
    lancia("rigenera")
elif a[0] == "--controlla":
    lancia("controlla")
elif a[0] == "--installa" and len(a) == 2:
    lancia("installa", "--da", str(SCIAME), "--radice", a[1])
elif a[0] == "--istruzioni":
    lancia("istruzioni")
elif a[0] == "--togli-istruzioni":
    lancia("istruzioni", "--togli")
elif a[0] == "--togli":
    lancia("rimuovi")
elif a[0] == "--elenco":
    lancia("professionisti")
else:
    print(__doc__)
    sys.exit(2)
#==== sciame.sh: file motore/giuria.py ====
#!/usr/bin/env python3
"""Lo sciame 4.0, protocollo G (sciame/GIURIA.md): conta i voti di una giuria e la soglia degli esperti nuovi.

    python3 -I sciame/giuria.py conta <cartella della giuria> <giro>
    python3 -I sciame/giuria.py richieste [sciame/RICHIESTE_ESPERTI.md]

`conta` ricalcola dai file sigillati tutti i giri da 0 a <giro> (non si fida degli ESITO già scritti), confronta i
sigilli con `SIGILLI.md` del cancelliere, controlla composizione, voti, non regressione, dipendenze e limite, e scrive
`ESITO_giro_<r>.json`. Esce con 0 se tutti i controlli passano, con 2 altrimenti (e allora non scrive niente).
Un ESITO già scritto deve coincidere con quello ricalcolato: un rivoto sullo stesso giro o un ESITO ritoccato sono un
errore. Non lancia agenti.
"""
import hashlib
import json
import re
import sys
from pathlib import Path

import os

QUI = Path(__file__).resolve().parent
BASE = QUI.parent if QUI.name == "motore" else QUI  # la cartella dello sciame
RADICE = Path(os.environ.get("SCIAME_RADICE", (BASE / (BASE / "RADICE").read_text(encoding="utf-8").strip()).resolve()
                             if (BASE / "RADICE").is_file() else BASE.parent))
AGENTI_DIR = Path(os.environ.get("SCIAME_AGENTI", RADICE / ".claude" / "agents"))
SIGILLO = re.compile(r"^sha256 dei byte che precedono questa riga: ([0-9a-f]{64})\s*$")
ID = r"(D[0-9A-Za-z_.-]+)"
RIGHE = {  # parola chiave → espressione della riga intera
    "OPZIONE": re.compile(rf"^OPZIONE {ID} (.+?)\s*$"),
    "OPZIONI": re.compile(rf"^OPZIONI {ID} (.+?)\s*$"),
    "DISPOSITIVO": re.compile(rf"^DISPOSITIVO {ID} (.+?)\s*$"),
    "DIPENDE": re.compile(rf"^DIPENDE {ID} {ID}\s*$"),
    "INCOMPATIBILE": re.compile(rf"^INCOMPATIBILE {ID} (.+?)\s*$"),
    "PROVA": re.compile(rf"^PROVA {ID} (.+?)\s*$"),
    "ESITO-PROVA": re.compile(rf"^ESITO-PROVA {ID} (passa|fallisce)\s*$"),
    "VOTO": re.compile(rf"^VOTO {ID} (si|sì|no)\s*$"),
    "REVISIONE": re.compile(rf"^REVISIONE {ID} (.+?)\s*$"),
    "CONDIZIONE": re.compile(rf"^CONDIZIONE {ID} (.+?)\s*$"),
    "CLASSE": re.compile(rf"^CLASSE {ID} (leggera|ordinaria|plenaria)\s*$"),
    "CAMBIO": re.compile(rf"^CAMBIO {ID} (.+?)\s*$"),
    "PREFERISCO": re.compile(rf"^PREFERISCO {ID} (.+?)\s*$"),
}
# quasi conforme: la parola chiave, in qualunque forma, in testa (dopo segni di elenco, citazione o grassetto) e
# seguita da un identificativo D…: «VOTO D1: no», «voto D1 si», «- VOTO D1 si», «**VOTO** D1». La prosa come
# «- **CONDIZIONE #1** …», «# Voto del…» o
# «classe (iii)» non lo è.
QUASI = re.compile(r"^[\s\-*>#]*(?i:(" + "|".join(sorted(RIGHE, key=len, reverse=True)) + r"))[\s:*]+D[0-9A-Za-z_.-]")
RUOLO = re.compile(r"^[a-z][a-z0-9-]*$")
AVVERSARI = {"avversario", "rovesciatore"}
PASSATA = {"logico", "debugger"}  # con un avversario: obbligatori in una giuria vincolante (GIURIA.md §2)
LIMITE_GIRI = 3
LIMITE_GIRI_LEGGERA = 1  # la giuria leggera ha un solo giro di revisione, poi passa alla giuria ordinaria
CRITICI = {"avversario", "rovesciatore", "debugger"}
FINALI = {"APPROVATA", "RACCOMANDATA", "RESPINTA", "NON_CONVERGENTE", "SOSPESA", "DA_PLENARIA", "DA_RIPROPORRE",
          "DA_GIURIA", "DA_UTENTE"}


def limite(g):
    return LIMITE_GIRI_LEGGERA if g.get("forma") == "leggera" else LIMITE_GIRI


class Errore(Exception):
    pass


def sha(dati):
    return hashlib.sha256(dati).hexdigest()


def sigillato(p):
    """(testo prima del sigillo, sigillo), se il sigillo coincide; altrimenti Errore."""
    if not p.is_file():
        raise Errore(f"manca {p}")
    dati = p.read_bytes()
    corpo, _, ultima = dati.rstrip(b"\n").rpartition(b"\n")
    m = SIGILLO.match(ultima.decode("utf-8", "replace"))
    if not m:
        raise Errore(f"{p.name}: ultima riga senza sigillo")
    corpo += b"\n"
    if sha(corpo) != m.group(1):
        raise Errore(f"{p.name}: il sigillo non coincide con i byte che lo precedono")
    return corpo.decode("utf-8"), m.group(1)


def righe_valide(testo, nome, ammesse):
    """Le righe del protocollo fuori dai blocchi ```; una riga quasi conforme è un errore."""
    trovate, dentro = [], False
    for n, riga in enumerate(testo.splitlines(), 1):
        if riga.lstrip().startswith("```"):
            dentro = not dentro
            continue
        if dentro:
            continue
        q = QUASI.match(riga)
        if not q:
            continue
        chiave = q.group(1).upper()
        m = RIGHE.get(chiave) and RIGHE[chiave].match(riga)
        if not m or chiave not in ammesse:
            raise Errore(f"{nome} r. {n}: riga non conforme o non ammessa qui: «{riga.strip()[:80]}»")
        trovate.append((chiave, m.groups()))
    if dentro:
        raise Errore(f"{nome}: blocco ``` non chiuso")
    return trovate


def ruoli_noti():
    if not AGENTI_DIR.is_dir():
        raise Errore(f"manca {AGENTI_DIR}")
    return {p.stem[len("sciame-"):] for p in AGENTI_DIR.glob("sciame-*.md")}


def leggi_giuria(cartella):
    p = cartella / "giuria.json"
    if not p.is_file():
        raise Errore("manca giuria.json")
    dati = p.read_bytes()
    try:
        g = json.loads(dati)
    except json.JSONDecodeError as x:
        raise Errore(f"giuria.json non è json: {x}")
    if not isinstance(g, dict):
        raise Errore("giuria.json: serve un oggetto")
    return g, sha(dati)


def controlla_composizione(cartella, g):
    errori = []
    for campo, tipo in (("oggetto", str), ("relatore", str), ("cancelliere", str), ("giurati", list),
                        ("tocca_codice", bool), ("tocca_numeri", bool), ("autorita", str), ("delega", str),
                        ("classificazione", str)):
        if not isinstance(g.get(campo), tipo):
            errori.append(f"campo «{campo}» mancante o di tipo sbagliato")
    if errori:
        raise Errore("giuria.json: " + "; ".join(errori))
    if g["autorita"] not in ("vincolante", "raccomandazione"):
        errori.append("autorita: «vincolante» o «raccomandazione»")
    if g["classificazione"] not in ("ordinaria", "plenaria"):
        errori.append("classificazione: «ordinaria» o «plenaria»")
    if g.get("protocollo", "G2") not in ("G2", "G1.1"):
        errori.append("protocollo: «G2» (di difetto) o «G1.1»")
    if g.get("forma", "ordinaria") not in ("ordinaria", "leggera"):
        errori.append("forma: «ordinaria» o «leggera»")
    leggera = g.get("forma") == "leggera"
    if g.get("limite_giri", limite(g)) != limite(g):
        errori.append(f"limite_giri: il protocollo lo fissa a {limite(g)}")
    noti = ruoli_noti()
    ruoli = []
    for x in g["giurati"]:
        if not isinstance(x, dict) or not isinstance(x.get("ruolo"), str):
            errori.append("un giurato senza «ruolo»")
            continue
        r = x["ruolo"]
        ruoli.append(r)
        if not RUOLO.match(r):
            errori.append(f"ruolo «{r}» non conforme a {RUOLO.pattern}")
        elif x.get("provvisorio"):
            try:
                sigillato(cartella / f"SCHEDA_{r}.md")
            except Errore as e:
                errori.append(f"esperto provvisorio «{r}» senza scheda sigillata: {e}")
        elif r not in noti:
            errori.append(f"ruolo «{r}» non è fra gli agenti dello sciame e non è segnato provvisorio")
    n = len(ruoli)
    if len(set(ruoli)) != n:
        errori.append("un ruolo compare due volte fra i giurati")
    plenaria = g["classificazione"] == "plenaria"
    for chi in ("relatore", "cancelliere"):
        if g[chi] in ruoli:
            errori.append(f"il {chi} ({g[chi]}) non può votare")
    if leggera and plenaria:
        errori.append("la giuria leggera non vale per una plenaria")
    if plenaria and g2(g) and (cartella / "PERTINENZA.md").is_file():
        attesi = pertinenti(cartella, g)
        if set(ruoli) != attesi:
            errori.append("plenaria: i votanti sono i pertinenti di PERTINENZA.md: mancano "
                          + (", ".join(sorted(attesi - set(ruoli))) or "nessuno") + "; in più "
                          + (", ".join(sorted(set(ruoli) - attesi)) or "nessuno"))
    elif plenaria:
        mancano = sorted(noti - set(ruoli) - {g["relatore"], g["cancelliere"]})
        if mancano:
            errori.append("plenaria: mancano i ruoli " + ", ".join(mancano))
        if not all(x.get("nuovo_sull_oggetto") for x in g["giurati"] if isinstance(x, dict)):
            errori.append("plenaria: al voto finale ogni ruolo vota con un'istanza nuova")
    elif leggera:
        if g["classificazione"] != "ordinaria":
            errori.append("la giuria leggera non vale per una plenaria")
        if n != 3:
            errori.append(f"giuria leggera: {n} giurati, ne servono 3 (competente, critico, garante)")
        if not CRITICI & set(ruoli):
            errori.append("giuria leggera: manca un critico (avversario, rovesciatore o debugger)")
        if not set(ruoli) - CRITICI - {"garante"}:
            errori.append("giuria leggera: manca il ruolo competente per la funzione")
    else:
        if not 5 <= n <= 9 or n % 2 == 0:
            errori.append(f"giurati {n}: servono da 5 a 9, in numero dispari")
        nuovi = sum(1 for x in g["giurati"] if isinstance(x, dict) and x.get("nuovo_sull_oggetto"))
        if 2 * nuovi < n:
            errori.append(f"istanze nuove sull'oggetto {nuovi} su {n}: servono almeno la metà")
        provv = sum(1 for x in g["giurati"] if isinstance(x, dict) and x.get("provvisorio"))
        if 3 * provv > n:
            errori.append(f"esperti provvisori {provv} su {n}: al più un terzo")
    if "garante" not in ruoli:
        errori.append("manca il garante dell'obiettivo")
    if not leggera:
        if not AVVERSARI & set(ruoli):
            errori.append("manca un avversario (avversario o rovesciatore)")
        if g["tocca_codice"] and "debugger" not in ruoli:
            errori.append("la decisione tocca codice e manca il debugger")
        if g["tocca_numeri"] and "statistico" not in ruoli:
            errori.append("la decisione tocca soglie o cifre e manca lo statistico")
        if g["autorita"] == "vincolante" and not PASSATA <= set(ruoli):
            errori.append("decisione vincolante: servono logico, debugger e un avversario")
    for p in cartella.glob("RINUNCIA_*.md"):
        if p.stem[len("RINUNCIA_"):] in ruoli:
            errori.append(f"{p.name}: chi rinuncia non può essere giurato")
    if errori:
        raise Errore("composizione: " + "; ".join(errori))
    return ruoli


def leggi_sigilli(cartella):
    p = cartella / "SIGILLI.md"
    if not p.is_file():
        raise Errore("manca SIGILLI.md: i sigilli riportati da relatore e giurati nelle loro risposte finali")
    out, verificate = {}, set()
    for riga in p.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^SIGILLO ((?:giro_\d+/)?[A-Za-z0-9_.-]+\.(?:md|json)) ([0-9a-f]{64})\s*$", riga)
        if m:
            out[m.group(1)] = m.group(2)
        m = re.match(r"^INCOMPATIBILE-VERIFICATO (giro_\d+) (D[0-9A-Za-z_.-]+)\s*$", riga)
        if m:  # il cancelliere conferma l'incompatibilità dichiarata dal relatore in quel giro
            verificate.add((m.group(1), m.group(2)))
    out["__incompatibili_verificate__"] = verificate
    return out


def g2(g):
    """Nella skill il protocollo G2 vale per difetto; "protocollo": "G1.1" solo per le giurie votate prima di lui."""
    return g.get("protocollo", "G2") == "G2"


def controlla_g2(cartella, g, sha_giuria, sigilli):
    """Protocollo G2: giuria.json sigillato prima del giro 0; nessun SIGILLO orfano; la delega e la pertinenza
    sigillate quando servono."""
    errori = []
    if sigilli.get("giuria.json") != sha_giuria:
        errori.append("SIGILLI.md: manca «SIGILLO giuria.json <sha>» uguale al file (G2: la giuria si fissa prima del giro 0)")
    for rel in sigilli:
        if rel.startswith("__"):
            continue
        if not (cartella / rel).is_file():
            errori.append(f"SIGILLI.md: SIGILLO orfano, {rel} non esiste")
    if g.get("autorita") == "vincolante":
        if g.get("delega") != "DELEGA.md":
            errori.append("G2: una giuria vincolante ha \"delega\": \"DELEGA.md\", con le righe «DELEGATA Dk»")
        else:
            con_sigillo_dichiarato(cartella, "DELEGA.md", sigilli)
    if g.get("classificazione") == "plenaria":
        if g.get("pertinenza") != "PERTINENZA.md":
            errori.append("G2: una plenaria ha \"pertinenza\": \"PERTINENZA.md\", con le righe «PERTINENTE <ruolo>»")
        else:
            con_sigillo_dichiarato(cartella, "PERTINENZA.md", sigilli)
    if errori:
        raise Errore("; ".join(errori))


def delegate(cartella, g):
    if not (g2(g) and g.get("autorita") == "vincolante"):
        return None
    testo = (cartella / "DELEGA.md").read_text(encoding="utf-8")
    return set(re.findall(r"^DELEGATA (D[0-9A-Za-z_.-]+)\s*$", testo, re.M))


def pertinenti(cartella, g):
    """I votanti di una plenaria G2: i ruoli PERTINENTE, con le deleghe dei sottoprofessionisti (DELEGA <sotto>
    <genitore>: il sottoprofessionista vota al posto del genitore, mai insieme)."""
    testo = (cartella / "PERTINENZA.md").read_text(encoding="utf-8")
    per = set(re.findall(r"^PERTINENTE ([a-z][a-z0-9-]*)\s*$", testo, re.M))
    for sotto, genitore in re.findall(r"^DELEGA ([a-z][a-z0-9-]*) ([a-z][a-z0-9-]*)\s*$", testo, re.M):
        if genitore in per:
            per.discard(genitore)
            per.add(sotto)
    return per - {g.get("relatore"), g.get("cancelliere")}


def con_sigillo_dichiarato(cartella, relativo, sigilli):
    testo, s = sigillato(cartella / relativo)
    if sigilli.get(relativo) != s:
        raise Errore(f"{relativo}: il sigillo non coincide con quello riportato in SIGILLI.md")
    return testo, s


def leggi_proposta(cartella, r, sigilli):
    testo, s = con_sigillo_dichiarato(cartella, f"giro_{r}/PROPOSTA.md", sigilli)
    righe = righe_valide(testo, f"giro_{r}/PROPOSTA.md", {"OPZIONE", "OPZIONI", "DISPOSITIVO", "DIPENDE", "INCOMPATIBILE",
                                                          "PROVA", "ESITO-PROVA"})
    p = {"sha": s, "opzione": {}, "opzioni": {}, "dispositivo": {}, "dipende": {}, "incompatibile": {}, "prova": {},
         "esito-prova": {}}
    for chiave, gr in righe:
        if chiave == "DIPENDE":
            p["dipende"].setdefault(gr[0], set()).add(gr[1])
            continue
        campo = chiave.lower()
        if gr[0] in p[campo]:
            raise Errore(f"giro_{r}/PROPOSTA.md: due righe {chiave} per {gr[0]}")
        if campo in ("prova", "esito-prova") and gr[0] not in p["opzione"] and False:
            pass
        p[campo][gr[0]] = gr[1]
    if not p["opzione"]:
        raise Errore(f"giro_{r}/PROPOSTA.md: nessuna riga OPZIONE")
    for d in p["opzione"]:
        if d not in p["dispositivo"]:
            raise Errore(f"giro_{r}/PROPOSTA.md: manca DISPOSITIVO {d}")
    for d in p["incompatibile"]:
        if d not in p["opzione"]:
            raise Errore(f"giro_{r}/PROPOSTA.md: INCOMPATIBILE su {d}, che non è in esame")
    if r == 0:
        for d, o in p["opzione"].items():
            lista = [x.strip() for x in p["opzioni"].get(d, "").split("|") if x.strip()]
            if o not in lista:
                raise Errore(f"giro_0/PROPOSTA.md: OPZIONE {d} «{o}» non è nella riga OPZIONI {d}")
    return p


def leggi_voto(cartella, r, ruolo, decisioni, sigilli, facoltative=frozenset()):
    rel = f"giro_{r}/VOTO_{ruolo}.md"
    testo, s = con_sigillo_dichiarato(cartella, rel, sigilli)
    v = {"sha": s, "voto": {}, "revisione": {}, "condizione": {}, "classe": {}, "cambio": {}, "preferisco": {}}
    for chiave, gr in righe_valide(testo, rel, {"VOTO", "REVISIONE", "CONDIZIONE", "CLASSE", "CAMBIO", "PREFERISCO"}):
        campo = chiave.lower()
        if gr[0] in facoltative:
            continue
        if gr[0] not in decisioni:
            raise Errore(f"{rel}: {chiave} su {gr[0]}, che non è in esame")
        if gr[0] in v[campo]:
            raise Errore(f"{rel}: due righe {chiave} per {gr[0]}")
        v[campo][gr[0]] = "si" if gr[1] == "sì" else gr[1]
    errori = []
    for d in decisioni:
        if d not in v["voto"]:
            errori.append(f"manca il voto su {d}")
            continue
        if v["voto"][d] == "no" and d not in v["revisione"]:
            errori.append(f"no su {d} senza REVISIONE")
        if v["voto"][d] == "si" and d not in v["condizione"]:
            errori.append(f"sì su {d} senza CONDIZIONE")
        if d not in v["classe"]:
            errori.append(f"manca CLASSE {d}")
    if errori:
        raise Errore(f"{rel}: " + "; ".join(errori))
    return v


def esito_conteggio(s, n):
    if s == n:
        return "APPROVATA"
    if 2 * s > n:
        return "REVISIONE"
    return "RESPINTA"


def calcola_giro(cartella, g, ruoli, r, prec, sigilli):
    giro = cartella / f"giro_{r}"
    if not giro.is_dir():
        raise Errore(f"manca la cartella giro_{r}")
    attesi = {"PROPOSTA.md"} | {f"VOTO_{x}.md" for x in ruoli}
    estranei = sorted(p.name for p in giro.iterdir() if p.name not in attesi)
    if estranei:
        raise Errore(f"giro_{r}: voci estranee " + ", ".join(estranei))
    p = leggi_proposta(cartella, r, sigilli)
    if g.get("forma") == "leggera":
        for d in p["opzione"]:
            if d not in p["prova"] or d not in p["esito-prova"]:
                raise Errore(f"giro_{r}/PROPOSTA.md: nella giuria leggera {d} vuole PROVA ed ESITO-PROVA (prova prima del voto)")
    if prec is None:
        if p["incompatibile"]:
            raise Errore("giro_0/PROPOSTA.md: INCOMPATIBILE vale solo nei giri di revisione")
    else:
        in_revisione = {d for d, e in prec["decisioni"].items() if e["stato"] == "REVISIONE"}
        if set(p["opzione"]) != in_revisione:
            raise Errore(f"giro_{r}/PROPOSTA.md: le decisioni devono essere quelle in REVISIONE "
                         f"({', '.join(sorted(in_revisione)) or 'nessuna'})")
        for d in p["opzione"]:
            e = prec["decisioni"][d]
            if p["opzione"][d] != e["opzione"]:
                raise Errore(f"giro_{r}: l'opzione di {d} è cambiata: è una proposta nuova, dal giro 0")
            if p["dispositivo"][d] != e["dispositivo"]:
                raise Errore(f"giro_{r}: il DISPOSITIVO di {d} è cambiato: non è una revisione piccola")
            if p["dipende"].get(d, set()) != set(e.get("dipende", [])):
                raise Errore(f"giro_{r}: le dipendenze di {d} sono cambiate")
    verificate = {d for (g, d) in sigilli.get("__incompatibili_verificate__", set()) if g == f"giro_{r}"}
    for d in verificate:
        if d not in p["incompatibile"]:
            raise Errore(f"SIGILLI.md: INCOMPATIBILE-VERIFICATO giro_{r} {d}, ma la proposta non lo dichiara")
    chiuse = {d for d in p["incompatibile"] if d in verificate}
    da_votare = [d for d in p["opzione"] if d not in chiuse]
    # Su una decisione dichiarata INCOMPATIBILE ma chiusa dal cancelliere, i voti sono ammessi e non contano.
    voti = {x: leggi_voto(cartella, r, x, da_votare, sigilli, facoltative=chiuse) for x in ruoli}
    n = len(ruoli)
    decisioni = {}
    for d in p["opzione"]:
        base = {"opzione": p["opzione"][d], "dispositivo": p["dispositivo"][d], "sha_proposta": p["sha"],
                "dipende": sorted(p["dipende"].get(d, set()))}
        if d in chiuse:
            decisioni[d] = dict(prec["decisioni"][d], stato="NON_CONVERGENTE",
                                incompatibile={"giro": r, "motivo": p["incompatibile"][d], "verificata": True})
            continue
        si = sorted(x for x in ruoli if voti[x]["voto"][d] == "si")
        no = sorted(x for x in ruoli if voti[x]["voto"][d] == "no")
        stato = esito_conteggio(len(si), n)
        voce = dict(base, si=si, no=no, stato=stato, giro_del_testo=r,
                    revisioni_chieste={x: voti[x]["revisione"][d] for x in no},
                    condizioni_dei_si={x: voti[x]["condizione"][d] for x in si},
                    classe_plenaria=sorted(x for x in ruoli if voti[x]["classe"][d] == "plenaria"),
                    preferenze={x: voti[x]["preferisco"][d] for x in ruoli if d in voti[x]["preferisco"]})
        if prec is not None:
            e = prec["decisioni"][d]
            persi = sorted(set(e["si"]) - set(si))
            # CAMBIO si chiede rispetto all'ultimo voto espresso dal giurato, anche in un giro scartato come regressivo.
            ultimi_no = e["regressiva"]["voti_del_giro"]["no"] if e.get("regressiva", {}).get("giro") == r - 1 else e["no"]
            senza_cambio = sorted(x for x in si if x in ultimi_no and d not in voti[x]["cambio"])
            if senza_cambio:
                raise Errore(f"giro_{r}: {d}, da no a sì senza riga CAMBIO: " + ", ".join(senza_cambio))
            if stato != "RESPINTA" and persi:
                # revisione regressiva: si scarta, restano il testo e i voti del giro precedente
                voce = dict(e, stato="REVISIONE",
                            regressiva={"giro": r, "si_persi": persi, "voti_del_giro": {"si": si, "no": no}})
        if g.get("forma") == "leggera":
            voce["prova"] = {"testo": p["prova"][d], "esito": p["esito-prova"][d]}
            classi = {voti[x]["classe"][d] for x in ruoli}
            if "plenaria" in classi:
                voce["stato"] = "DA_PLENARIA"
            elif "ordinaria" in classi:
                voce["stato"] = "DA_GIURIA"
                voce["motivo"] = "un giurato la classifica ordinaria: va alla giuria ordinaria"
            elif voce["stato"] in ("APPROVATA", "REVISIONE") and p["esito-prova"][d] == "fallisce":
                voce["stato"] = "RESPINTA"
                voce["motivo"] = "la prova veloce fallisce"
        if g2(g) and prec is None:
            fuori = sorted(x for x, o in voce.get("preferenze", {}).items()
                           if o not in [y.strip() for y in p["opzioni"].get(d, "").split("|")])
            if fuori:
                raise Errore(f"{d}: PREFERISCO fuori dall'elenco OPZIONI ({', '.join(fuori)})")
        if voce["stato"] == "APPROVATA":
            pref = {}
            for o in voce["preferenze"].values():
                if o != voce["opzione"]:
                    pref[o] = pref.get(o, 0) + 1
            migliore = max(pref.items(), key=lambda kv: kv[1], default=(None, 0))
            if voce["classe_plenaria"] and g.get("forma") != "leggera" and not (
                    g2(g) and g.get("classificazione") == "plenaria"):
                voce["stato"] = "DA_PLENARIA"
            elif 2 * migliore[1] > n:
                voce["stato"] = "DA_RIPROPORRE"
                voce["da_riproporre_con"] = migliore[0]
            elif g["autorita"] == "raccomandazione":
                voce["stato"] = "RACCOMANDATA"
            elif delegate(cartella, g) is not None and d not in delegate(cartella, g):
                voce["stato"] = "RACCOMANDATA"
                voce["motivo"] = "la decisione non è fra quelle delegate in DELEGA.md"
        if voce["stato"] == "REVISIONE" and r == limite(g):
            voce["stato"] = "DA_GIURIA" if g.get("forma") == "leggera" else "NON_CONVERGENTE"
        decisioni[d] = voce
    if prec is not None:
        for d, e in prec["decisioni"].items():
            decisioni.setdefault(d, e)
    # dipendenze: un'approvata che dipende da una non approvata non diventa atto
    for _ in range(len(decisioni)):
        for d, e in decisioni.items():
            for dj in e.get("dipende", []):
                if dj not in decisioni:
                    raise Errore(f"{d} dipende da {dj}, che non è fra le decisioni della giuria")
                sj = decisioni[dj]["stato"]
                if sj == "REVISIONE" and e["stato"] in ("APPROVATA", "RACCOMANDATA"):
                    e["stato"] = "REVISIONE"
                    e["in_attesa_di"] = dj
                elif sj in FINALI - {"APPROVATA", "RACCOMANDATA"} and e["stato"] not in ("RESPINTA",):
                    if e["stato"] != "SOSPESA":
                        e["stato"] = "SOSPESA"
                        e["sospesa_per"] = {"dipende_da": dj, "stato": sj}
    return {"giro": r, "giurati": ruoli, "n": n, "limite_giri": limite(g), **({"forma": "leggera"} if g.get("forma") == "leggera" else {}), "protocollo": g.get("protocollo", "G2"),
            "sha_voti": {x: voti[x]["sha"] for x in ruoli}, "decisioni": decisioni}


def precedenti(cartella, g, e, k):
    """G2: le giurie precedenti sulla stessa domanda (giuria.json "precedenti", cartelle relative alla cartella madre).
    Un'opzione già RESPINTA non si ripropone; un secondo DA_RIPROPORRE sulla stessa decisione diventa DA_UTENTE."""
    if k != 0:
        return
    for rel in g.get("precedenti", []):
        if Path(rel).is_absolute() or ".." in Path(rel).parts or "/" in rel:
            raise Errore(f"precedenti: «{rel}» non ammesso")
        c = (cartella.parent / rel).resolve()
        esiti = sorted(c.glob("ESITO_giro_*.json"))
        if not esiti:
            raise Errore(f"precedenti: {rel} non ha un ESITO")
        vecchio = json.loads(esiti[-1].read_text(encoding="utf-8"))["decisioni"]
        for d, v in e["decisioni"].items():
            w = vecchio.get(d)
            if not w:
                continue
            if w["stato"] == "RESPINTA" and w["opzione"] == v["opzione"]:
                raise Errore(f"{d}: l'opzione «{v['opzione']}» è già RESPINTA in {rel}: non si ripropone")
            if w["stato"] == "DA_RIPROPORRE" and v["stato"] == "DA_RIPROPORRE":
                v["stato"] = "DA_UTENTE"
                v["motivo"] = f"secondo DA_RIPROPORRE dopo {rel}: decide l'utente"


def conta(cartella, r):
    cartella = Path(cartella)
    if not isinstance(r, int) or r < 0:
        raise Errore("il giro è un intero ≥ 0")
    g, sha_giuria = leggi_giuria(cartella)
    if r > limite(g):
        raise Errore(f"giro {r} oltre il limite ({limite(g)})")
    if not g2(g) and os.environ.get("SCIAME_G11_PROVE") != "1":
        e0 = cartella / "ESITO_giro_0.json"
        if not e0.is_file() or '"protocollo"' in e0.read_text(encoding="utf-8"):
            raise Errore("protocollo G1.1: ammesso solo per ricontare le giurie votate prima di G2 (un ESITO_giro_0.json "
                         "senza la chiave «protocollo»); una giuria nuova segue G2")
    ruoli = controlla_composizione(cartella, g)
    sigilli = leggi_sigilli(cartella)
    if g2(g):
        controlla_g2(cartella, g, sha_giuria, sigilli)
    prec = None
    for k in range(r + 1):
        e = calcola_giro(cartella, g, ruoli, k, prec, sigilli)
        e["sha_giuria"] = sha_giuria
        p = cartella / f"ESITO_giro_{k}.json"
        if g2(g):
            precedenti(cartella, g, e, k)
        testo = json.dumps(e, ensure_ascii=False, indent=1, sort_keys=True) + "\n"
        if p.exists():
            vecchio = p.read_text(encoding="utf-8")
            if '"protocollo"' not in vecchio:
                senza = {a: b for a, b in e.items() if a != "protocollo"}
                testo = json.dumps(senza, ensure_ascii=False, indent=1, sort_keys=True) + "\n"
            if vecchio != testo:
                raise Errore(f"{p.name} esiste e non coincide con il ricalcolo: rivoto, voto cambiato, "
                             f"giuria.json cambiata o ESITO ritoccato")
        elif k < r:
            raise Errore(f"manca {p.name}: i giri si contano in ordine")
        if k < r and not any(v["stato"] == "REVISIONE" for v in e["decisioni"].values()):
            raise Errore(f"dopo il giro {k} nessuna decisione è in REVISIONE: il giro {r} non esiste")
        prec = e
    uscita = cartella / f"ESITO_giro_{r}.json"
    if uscita.is_symlink():
        raise Errore(f"{uscita.name} è un collegamento simbolico: non lo seguo")
    uscita.write_text(testo, encoding="utf-8")
    return prec


# ---- §4, gli esperti che non esistono ancora ----

RIGA_TABELLA = re.compile(r"^\|\s*\d{4}")
RIGA_RICHIESTA = re.compile(
    r"^\|\s*(\d{4}-\d{2}-\d{2})\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*`([a-z0-9-]+)`\s*\|\s*([^|]+?)\s*\|\s*([^|]*?)\s*\|\s*$")
RIGA_CHIUSA = re.compile(r"^- `([a-z0-9-]+)`: (creato|created|(?:unito a|merged into) `([a-z0-9-]+)`)")


def normalizza_richiedente(chi, noti):
    c = chi.strip().lower()
    if c.startswith("sciame-"):
        c = c[len("sciame-"):]
    if c == "coordinatore" or c in noti:
        return c
    if c.startswith("provvisorio:") and RUOLO.match(c[len("provvisorio:"):]):
        return c
    raise Errore(f"richiedente «{chi}» non è un ruolo dello sciame, «coordinatore» o «provvisorio:<sigla>»")


def richieste(registro, radice=None):
    radice = Path(radice) if radice else RADICE
    noti = ruoli_noti()
    righe = Path(registro).read_text(encoding="utf-8").splitlines()
    creati, uniti = set(), {}
    for riga in righe:
        m = RIGA_CHIUSA.match(riga)
        if m:
            if m.group(2) in ("creato", "created"):
                creati.add(m.group(1))
            else:
                uniti[m.group(1)] = m.group(3)
    per_sigla = {}
    for n, riga in enumerate(righe, 1):
        if not RIGA_TABELLA.match(riga):
            continue
        m = RIGA_RICHIESTA.match(riga)
        if not m:
            raise Errore(f"registro r. {n}: riga non conforme «{riga[:80]}»")
        _, conv, chi, sigla, _, motivo = m.groups()
        if len(motivo) < 10:
            raise Errore(f"registro r. {n}: motivo assente o troppo breve")
        if not (radice / conv).is_dir():
            raise Errore(f"registro r. {n}: la convocazione «{conv}» non è una cartella d'archivio esistente")
        chi = normalizza_richiedente(chi, noti)
        while sigla in uniti:
            sigla = uniti[sigla]
        if sigla in creati:
            continue
        if chi == f"provvisorio:{sigla}":
            continue  # l'esperto provvisorio non chiede la propria creazione
        per_sigla.setdefault(sigla, set()).add((conv, chi))
    soglia = {}
    for sigla, coppie in per_sigla.items():
        coord = sorted(c for c in coppie if c[1] == "coordinatore")[:1]
        agenti = {c for c in coppie if c[1] != "coordinatore"}
        conteggiate = agenti | set(coord)
        conv = {}
        for c, chi in agenti:
            conv.setdefault(c, set()).add(chi)
        tutte_conv = {c for c, _ in conteggiate}
        a = sorted(c for c, chi in conv.items() if len(chi) >= (5 if "plenaria" in c else 3))
        richiedenti = {chi for _, chi in agenti}
        b = len(conteggiate) >= 3 and len(tutte_conv) >= 2 and len(richiedenti) >= 2
        soglia[sigla] = {"richieste": len(conteggiate), "convocazioni": len(tutte_conv),
                         "richiedenti": len(richiedenti), "contemporanea": a, "accumulata": b,
                         "da_creare": bool(a) or b}
    return soglia


def main():
    a = sys.argv[1:]
    try:
        if a[:1] == ["conta"] and len(a) == 3:
            try:
                giro = int(a[2])
            except ValueError:
                raise Errore("il giro è un intero ≥ 0")
            e = conta(a[1], giro)
            for d, v in sorted(e["decisioni"].items()):
                extra = ""
                if v.get("regressiva", {}).get("giro") == e["giro"]:
                    vg = v["regressiva"]["voti_del_giro"]
                    extra = f" (revisione regressiva scartata: sì del giro {len(vg['si'])}/{e['n']})"
                print(f"{d}: {v['stato']}{extra} — sì {len(v.get('si', []))}/{e['n']} — {v['opzione']}")
        elif a[:1] == ["richieste"] and len(a) <= 2:
            reg = a[1] if len(a) == 2 else str(BASE / "RICHIESTE_ESPERTI.md")
            s = richieste(reg)
            for sigla, v in sorted(s.items()):
                print(f"{sigla}: {v['richieste']} richieste, {v['convocazioni']} convocazioni, "
                      f"{v['richiedenti']} richiedenti — {'DA CREARE' if v['da_creare'] else 'sotto la soglia'}")
            if not s:
                print("nessuna richiesta aperta")
            sigle = sorted(s)
            vicine = [(x, y) for i, x in enumerate(sigle) for y in sigle[i + 1:] if x[:5] == y[:5]]
            for x, y in vicine:
                print(f"sigle vicine, da unire o da distinguere con un motivo: {x}, {y}")
        else:
            print(__doc__)
            sys.exit(2)
    except Errore as x:
        print(f"ERRORE: {x}")
        sys.exit(2)
    except (OSError, ValueError, KeyError, TypeError) as x:
        print(f"ERRORE: {type(x).__name__}: {x}")
        sys.exit(2)


if __name__ == "__main__":
    main()
