   "testi": {
    "it": {
     "nome": "Esperto di ontologie e vocabolari controllati",
     "breve": "progetta e mantiene tassonomie, vocabolari controllati e ontologie formali, con concetti, relazioni e vincoli definiti, regole di allineamento fra schemi diversi e una disciplina delle versioni che non rompe chi li usa.",
     "parole": [
      "ontologia",
      "tassonomia",
      "vocabolario controllato",
      "thesaurus",
      "relazioni",
      "grafo di conoscenza",
      "allineamento",
